rtl:
module Adder4Bit(S, V, A, B, Cin);
    output [3:0] S;
    output V;
    input [3:0] A, B;
    input Cin;

    wire [3:0] sum;
    wire carry_out;

    assign {carry_out, sum} = A + B + Cin;
    assign S = sum;
    assign V = (sum > 4'hF) ? 1 : 0;
endmodule

sva:
module Adder4Bit_sva (
    input logic clk,
    input logic [3:0] S,
    input logic V,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin
);

// S matches the implemented 4-bit addition result.
    check_sum_function: assert property (
        @(posedge clk) S == ((A + B + Cin) & 4'hF)
    );

// V is always low in the implemented logic.
    check_v_always_low: assert property (
        @(posedge clk) V == 1'b0
    );

// With B and Cin low, S passes A through.
    check_pass_a_when_b_and_cin_zero: assert property (
        @(posedge clk) ((B == 4'h0) && (Cin == 1'b0)) |-> (S == A)
    );

// With A and Cin low, S passes B through.
    check_pass_b_when_a_and_cin_zero: assert property (
        @(posedge clk) ((A == 4'h0) && (Cin == 1'b0)) |-> (S == B)
    );

// With both operands low, S reflects Cin in bit 0.
    check_zero_operands_reflect_cin: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0)) |-> (S == {3'b000, Cin})
    );

// All-zero inputs produce zero outputs.
    check_all_zero_inputs: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0) && (Cin == 1'b0)) |-> ((S == 4'h0) && (V == 1'b0))
    );

endmodule

rtl:
module multiplexer_system (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [3:0] out
);

reg [3:0] mux1_out;
reg [3:0] and_out;

// 6-to-1 multiplexer to select data input based on sel
always @*
begin
    case (sel)
        3'b000: mux1_out = data0;
        3'b001: mux1_out = data1;
        3'b010: mux1_out = data2;
        3'b011: mux1_out = data3;
        3'b100: mux1_out = data4;
        3'b101: mux1_out = data5;
        default: mux1_out = 4'b0;
    endcase
end

// Generate bitwise AND of two least significant bits of all data inputs
always @*
begin
    case (sel)
        3'b110: and_out = &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]};
        3'b111: and_out = &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]};
        default: and_out = 4'b0;
    endcase
end

// 6-to-1 multiplexer to select between mux1_out and and_out
always @*
begin
    case (sel)
        3'b110: out = and_out;
        3'b111: out = and_out;
        default: out = mux1_out;
    endcase
end

endmodule

sva:
module multiplexer_system_sva (
    input logic        clk,
    input logic [2:0]  sel,
    input logic [3:0]  data0,
    input logic [3:0]  data1,
    input logic [3:0]  data2,
    input logic [3:0]  data3,
    input logic [3:0]  data4,
    input logic [3:0]  data5,
    input logic [3:0]  out
);

// sel=000 routes data0 to out.
    check_sel_000_routes_data0: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out == data0)
    );

// sel=001 routes data1 to out.
    check_sel_001_routes_data1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out == data1)
    );

// sel=010 routes data2 to out.
    check_sel_010_routes_data2: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out == data2)
    );

// sel=011 routes data3 to out.
    check_sel_011_routes_data3: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out == data3)
    );

// sel=100 routes data4 to out.
    check_sel_100_routes_data4: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out == data4)
    );

// sel=101 routes data5 to out.
    check_sel_101_routes_data5: assert property (
        @(posedge clk) (sel == 3'b101) |-> (out == data5)
    );

// sel=110 drives the zero-extended reduction-AND result.
    check_sel_110_routes_and_result: assert property (
        @(posedge clk) (sel == 3'b110) |-> (out == {3'b000, &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]}})
    );

// sel=111 drives the same zero-extended reduction-AND result.
    check_sel_111_routes_and_result: assert property (
        @(posedge clk) (sel == 3'b111) |-> (out == {3'b000, &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]}})
    );

endmodule

