module sky130_fd_sc_lp__o221ai (
    Y   ,
    A1  ,
    A2  ,
    B1  ,
    B2  ,
    C1  ,
    VPWR,
    VGND
);

    output Y   ;
    input  A1  ;
    input  A2  ;
    input  B1  ;
    input  B2  ;
    input  C1  ;
    input  VPWR;
    input  VGND;

    assign Y = A1 & A2 & B1 & B2 & C1 & VPWR & VGND;

endmodule

sva:
module sky130_fd_sc_lp__o221ai_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic VPWR,
    input logic VGND
);

// Y must equal the AND of all inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & B1 & B2 & C1 & VPWR & VGND)
    );

// All inputs high must drive Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & B2 & C1 & VPWR & VGND) |-> Y
    );

// Y high requires every input to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & B1 & B2 & C1 & VPWR & VGND)
    );

// A1 low must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A2 low must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// B1 low must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// B2 low must force Y low.
    check_b2_low_forces_y_low: assert property (
        @(posedge clk) !B2 |-> !Y
    );

// C1 low must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// VPWR low must force Y low.
    check_vpwr_low_forces_y_low: assert property (
        @(posedge clk) !VPWR |-> !Y
    );

// VGND low must force Y low.
    check_vgnd_low_forces_y_low: assert property (
        @(posedge clk) !VGND |-> !Y
    );

endmodule

module reg_module_sva (
    input logic       clk,
    input logic       reset,
    input logic       wenb,
    input logic [7:0] in_data,
    input logic [7:0] reg_out
);

// Reset clears the register on the next sampled cycle.
    check_reset_clears_reg: assert property (
        @(posedge clk) reset |=> (reg_out == 8'h00)
    );

// Reset has priority over write enable.
    check_reset_priority_over_write: assert property (
        @(posedge clk) (reset && wenb) |=> (reg_out == 8'h00)
    );

// A write captures in_data into reg_out.
    check_write_updates_reg: assert property (
        @(posedge clk) disable iff (reset)
        wenb |=> (reg_out == $past(in_data))
    );

// Without a write, the register holds its previous value.
    check_hold_without_write: assert property (
        @(posedge clk) disable iff (reset)
        !wenb |=> (reg_out == $past(reg_out))
    );

endmodule

rtl:
module up_counter(
    input clk, // clock signal
    input reset, // reset signal
    output reg [2:0] count // output count
);

    always @(posedge clk) begin
        if (reset) begin // reset counter to 0
            count <= 3'b0;
        end else begin // increment counter
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva (
    input logic clk,
    input logic reset,
    input logic [2:0] count
);

// Active-high reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

// From 0, the counter increments to 1.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd0) |=> (count == 3'd1)
    );

// From 1, the counter increments to 2.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd1) |=> (count == 3'd2)
    );

// From 2, the counter increments to 3.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd2) |=> (count == 3'd3)
    );

// From 3, the counter increments to 4.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd3) |=> (count == 3'd4)
    );

// From 4, the counter increments to 5.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd4) |=> (count == 3'd5)
    );

// From 5, the counter increments to 6.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd5) |=> (count == 3'd6)
    );

// From 6, the counter increments to 7.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd6) |=> (count == 3'd7)
    );

// From 7, the counter wraps back to 0.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd7) |=> (count == 3'd0)
    );

endmodule

rtl:
module draw_block(
	input clock,
	input [10:0] vcounter,
	input [11:0] hcounter,
	input [2:0] block,
	output [4:0] sel_row, sel_col,
	output reg [3:0] out
);

parameter LEFT = 160;
parameter TOP = 0;
parameter MAXX = 320;
parameter MAXY = 480;

wire range;
assign range = hcounter >= LEFT && hcounter < LEFT+MAXX && vcounter >= TOP && vcounter < TOP+MAXY;

assign sel_col = (hcounter-LEFT)/32;
assign sel_row = (vcounter-TOP)/16;

reg rev;
always @(posedge clock)
	rev <= ~rev;


always @(*)
begin
	if (range) begin 
		if (block == 3'b000)
			out = 4'b0000; 
		else if(~block[2]) begin : tenmulten integer i, j;                                             
			i = (hcounter-LEFT)%32;
			j = (vcounter-TOP)%16;

			if (i>8 && i<23) begin
				if (j==0 || j==15) out = 4'b1000;
				else case (block[1:0])
					2'b00: out = 4'b0000; 2'b01: out = 4'b1100; 2'b10: out = 4'b1011; 2'b11: out = 4'b1101; endcase
				end else if (i==8 || i==23)
				out = 4'b1000; 
			else case(block[1:0])
				2'b11:	if(i==0 || i==31 || j==0 || j==15) out = 4'b1000;
					else out = 4'b1110; default:out = 4'b0000;
			endcase	

		end else if (block[2]) begin : twentymulten integer i,j;
			i = (hcounter-LEFT)%32;
			j = (vcounter-TOP)%16;
			if (i==0 || i==31 || j==0 || j==15) out = 4'b1000;
			else begin
				case (block[1:0])
					2'b00: out = 4'b1001; 2'b01: out = 4'b1010; 2'b10: out = 4'b1110; 2'b11: out = 4'b1111 ; endcase
			end
			end
	end else
		out = 4'b0000;
end
endmodule

