module draw_block_assertions(
    input logic clock,
    input logic [10:0] vcounter,
    input logic [11:0] hcounter,
    input logic [2:0] block,
    input logic [4:0] sel_row,
    input logic [4:0] sel_col,
    input logic [3:0] out
);

// sel_col matches the 32-pixel horizontal tile index in the draw region.
check_sel_col_decode: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT))
    |-> (sel_col == ((hcounter - LEFT) / TILE_W))
);

// sel_row matches the 16-pixel vertical tile index in the draw region.
check_sel_row_decode: assert property (
    @(posedge clock)
    (vcounter < BOTTOM)
    |-> (sel_row == (vcounter / TILE_H))
);

// out is blank outside the active drawing window.
check_out_zero_outside_window: assert property (
    @(posedge clock)
    (!((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM)))
    |-> (out == 4'b0000)
);

// block 000 always produces blank output in range.
check_block_zero_blank: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b000))
    |-> (out == 4'b0000)
);

// Nonzero narrow blocks draw 8 on the top and bottom of the center strip.
check_narrow_center_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     (((vcounter % TILE_H) == 11'd0) || ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 001 fills the center strip interior with 1100.
check_narrow_center_fill_block_001: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b001) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1100)
);

// block 010 fills the center strip interior with 1011.
check_narrow_center_fill_block_010: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b010) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1011)
);

// block 011 fills the center strip interior with 1101.
check_narrow_center_fill_block_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1101)
);

// Nonzero narrow blocks draw 8 on the two center-strip side columns.
check_narrow_side_columns_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd8) ||
      (((hcounter - LEFT) % TILE_W) == 12'd23)))
    |-> (out == 4'b1000)
);

// Narrow blocks other than 011 are blank in the outer columns.
check_narrow_outer_blank_non_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block[2] == 1'b0) && (block[1:0] != 2'b11) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)))
    |-> (out == 4'b0000)
);

// block 011 draws 8 on the tile border in the outer columns.
check_narrow_outer_block_011_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd0) ||
      (((hcounter - LEFT) % TILE_W) == 12'd31) ||
      ((vcounter % TILE_H) == 11'd0) ||
      ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 011 fills the outer-column tile interior with 1110.
check_narrow_outer_block_011_fill: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1110)
);

// Wide blocks draw 8 on the tile border.
check_wide_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block[2] == 1'b1) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd0) ||
      (((hcounter - LEFT) % TILE_W) == 12'd31) ||
      ((vcounter % TILE_H) == 11'd0) ||
      ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 100 fills the wide tile interior with 1001.
check_wide_fill_block_100: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b100) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1001)
);

// block 101 fills the wide tile interior with 1010.
check_wide_fill_block_101: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b101) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1010)
);

// block 110 fills the wide tile interior with 1110.
check_wide_fill_block_110: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b110) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1110)
);

// block 111 fills the wide tile interior with 1111.
check_wide_fill_block_111: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b111) &&
     (((hcounter - LEFT) % TILE_W) != 12'd0) &&
     (((hcounter - LEFT) % TILE_W) != 12'd31) &&
     ((vcounter % TILE_H) != 11'd0) &&
     ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1111)
);

endmodule

rtl:
module myNAND3 (IN1,IN2,IN3,QN);

input IN1,IN2,IN3;
output QN;

wire nand1, nand2;

nand (nand1, IN1, IN2, IN3);
nand (nand2, nand1, nand1);
not (QN, nand2);

endmodule

sva:
module myNAND3_sva (
    input logic clk,
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic QN
);

// QN must equal the 3-input NAND of IN1, IN2, and IN3.
    check_nand3_function: assert property (
        @(posedge clk) QN == ~(IN1 & IN2 & IN3)
    );

// When all inputs are high, QN must be low.
    check_all_high_drives_low: assert property (
        @(posedge clk) (IN1 && IN2 && IN3) |-> !QN
    );

// If IN1 is low, QN must be high.
    check_in1_low_drives_high: assert property (
        @(posedge clk) !IN1 |-> QN
    );

// If IN2 is low, QN must be high.
    check_in2_low_drives_high: assert property (
        @(posedge clk) !IN2 |-> QN
    );

// If IN3 is low, QN must be high.
    check_in3_low_drives_high: assert property (
        @(posedge clk) !IN3 |-> QN
    );

// A low QN is only possible when all three inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) !QN |-> (IN1 && IN2 && IN3)
    );

endmodule

rtl:
module four_to_one (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    wire A_low, A_high, B_low, B_high;

    assign A_low = ~(A1 | A2);
    assign A_high = A1 & A2;
    assign B_low = ~(B1 | B2);
    assign B_high = B1 & B2;

    assign X = (A_low & B_low) | (A_high & B_high);

endmodule

sva:
module four_to_one_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic X
);

// X matches the implemented sum-of-products function.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == (((~(A1 | A2)) & (~(B1 | B2))) | ((A1 & A2) & (B1 & B2)))
    );

// All four inputs low drives X high.
    check_all_low_sets_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (!B1 && !B2)) |-> X
    );

// All four inputs high drives X high.
    check_all_high_sets_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (B1 && B2)) |-> X
    );

// A mixed pair cannot produce X high.
    check_mixed_a_clears_x: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> !X
    );

// B mixed pair cannot produce X high.
    check_mixed_b_clears_x: assert property (
        @(posedge clk)
        (B1 ^ B2) |-> !X
    );

// A low pair with B high pair drives X low.
    check_a_low_b_high_clears_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (B1 && B2)) |-> !X
    );

// A high pair with B low pair drives X low.
    check_a_high_b_low_clears_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (!B1 && !B2)) |-> !X
    );

// X can only be high for matching all-low or all-high pairs.
    check_x_high_only_on_matching_extremes: assert property (
        @(posedge clk)
        X |-> (((!A1 && !A2) && (!B1 && !B2)) || ((A1 && A2) && (B1 && B2)))
    );

endmodule

module power_of_2_detection_sva (
    input logic        clk,
    input logic [15:0] num,
    input logic        is_power_of_2
);

// Zero must not be flagged as a power of two.
    check_zero_is_not_power_of_two: assert property (
        @(posedge clk) (num == 16'd0) |-> (is_power_of_2 == 1'b0)
    );

// A one-hot input must be flagged as a power of two.
    check_onehot_input_sets_output: assert property (
        @(posedge clk) $onehot(num) |-> (is_power_of_2 == 1'b1)
    );

// A nonzero input with multiple bits set must clear the output.
    check_multibit_input_clears_output: assert property (
        @(posedge clk) ((num != 16'd0) && !$onehot(num)) |-> (is_power_of_2 == 1'b0)
    );

// A high output must only occur for a one-hot input.
    check_high_output_requires_onehot_input: assert property (
        @(posedge clk) (is_power_of_2 == 1'b1) |-> $onehot(num)
    );

// The output must match the RTL power-of-two detection expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk) (is_power_of_2 == (((num != 16'd0) && ((num & (num - 16'd1)) == 16'd0)) ? 1'b1 : 1'b0))
    );

endmodule

rtl:
module sky130_fd_sc_ls__inv (
    Y,
    A
);

    output Y;
    input  A;

    wire not0_out_Y;

    not not0 (not0_out_Y, A              );
    buf buf0 (Y         , not0_out_Y     );

endmodule

sva:
module sky130_fd_sc_ls__inv_sva (
    input logic clk,
    input logic Y,
    input logic A
);

// Y must always be the bitwise inversion of A.
    check_output_is_inverse: assert property (
        @(posedge clk) (Y === ~A)
    );

// A low input drives Y high.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input drives Y low.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// Unknown or high-impedance input produces an unknown output.
    check_unknown_input_produces_unknown_output: assert property (
        @(posedge clk) ((A === 1'bx) || (A === 1'bz)) |-> (Y === 1'bx)
    );

endmodule

module counter_sva (
    input logic       CLK,
    input logic       RST,
    input logic       enable,
    input logic [3:0] count_out
);

// Reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge CLK) RST |=> (count_out == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge CLK) disable iff (RST)
        enable |=> (count_out == ($past(count_out) + 4'b0001))
    );

// When disabled outside reset, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge CLK) disable iff (RST)
        !enable |=> (count_out == $past(count_out))
    );

// Counting from 4'hF wraps the counter to 4'h0.
    check_wraps_after_max: assert property (
        @(posedge CLK) disable iff (RST)
        (enable && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// Reset takes priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge CLK)
        (RST && enable) |=> (count_out == 4'b0000)
    );

endmodule

rtl:
module xor_adder (
  input clk,
  input [1:0] a,
  input [1:0] b,
  output reg [1:0] sum
);

  always @(posedge clk) begin
    sum <= a ^ b;
  end

endmodule

sva:
module xor_adder_sva (
    input logic       clk,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic [1:0] sum
);

// Sum captures the previous cycle XOR of a and b.
    check_sum_registers_prev_xor: assert property (
        @(posedge clk) 1'b1 |=> (sum == ($past(a) ^ $past(b)))
    );

// Equal inputs produce a zero sum on the next clock.
    check_equal_inputs_produce_zero: assert property (
        @(posedge clk) (a == b) |=> (sum == 2'b00)
    );

// A zero a input passes b through to sum on the next clock.
    check_zero_a_passthrough_b: assert property (
        @(posedge clk) (a == 2'b00) |=> (sum == $past(b))
    );

// A zero b input passes a through to sum on the next clock.
    check_zero_b_passthrough_a: assert property (
        @(posedge clk) (b == 2'b00) |=> (sum == $past(a))
    );

endmodule

rtl:
module hc161_like ( input  wire [3:0] cpu_d
							, input  wire cpu_rw
							, input  wire Ncpu_romsel
							, output wire hc161_out0
							, output wire hc161_out1
							, output wire hc161_out2
							, output wire hc161_out3
							);
	reg [3:0] hc161_krn; assign hc161_out0 = hc161_krn [0:0];
	assign hc161_out1 = hc161_krn [1:1];
	assign hc161_out2 = hc161_krn [2:2];
	assign hc161_out3 = hc161_krn [3:3]; always @(posedge Ncpu_romsel) begin
		if (!cpu_rw) begin
			hc161_krn <= cpu_d; 
		end
	end

endmodule

sva:
module hc161_like_sva (
    input logic [3:0] cpu_d,
    input logic       cpu_rw,
    input logic       Ncpu_romsel,
    input logic       hc161_out0,
    input logic       hc161_out1,
    input logic       hc161_out2,
    input logic       hc161_out3
);

// A write cycle loads all four outputs from cpu_d.
    check_write_loads_outputs: assert property (
        @(posedge Ncpu_romsel)
        (cpu_rw === 1'b0) |=> (
            {hc161_out3, hc161_out2, hc161_out1, hc161_out0} ===
            {$past(cpu_d[3]), $past(cpu_d[2]), $past(cpu_d[1]), $past(cpu_d[0])}
        )
    );

// A non-write cycle leaves all four outputs unchanged.
    check_read_holds_outputs: assert property (
        @(posedge Ncpu_romsel)
        (cpu_rw === 1'b1) |=> (
            {hc161_out3, hc161_out2, hc161_out1, hc161_out0} ===
            {$past(hc161_out3), $past(hc161_out2), $past(hc161_out1), $past(hc161_out0)}
        )
    );

endmodule

module adder_sva(
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic clk,
    input logic rst,
    input logic signed [15:0] sum
);

// Sum matches the operation taken on the previous clock edge.
    check_sum_matches_previous_cycle_operation: assert property (
        @(posedge clk)
        1'b1 |=> (sum == ($past(rst) ? 16'sd0 : ($past(a) + $past(b))))
    );

// A reset cycle drives sum to zero.
    check_reset_clears_sum: assert property (
        @(posedge clk)
        rst |=> (sum == 16'sd0)
    );

// A non-reset cycle loads the previous sum of a and b.
    check_sum_updates_after_nonreset_cycle: assert property (
        @(posedge clk) disable iff (rst)
        !rst |=> (sum == ($past(a) + $past(b)))
    );

// With a equal to zero, sum passes through the previous value of b.
    check_zero_a_passes_b: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (a == 16'sd0)) |=> (sum == $past(b))
    );

// With b equal to zero, sum passes through the previous value of a.
    check_zero_b_passes_a: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (b == 16'sd0)) |=> (sum == $past(a))
    );

endmodule

module sky130_fd_sc_hdll__nand4bb_sva (
    input logic clk,
    input logic A_N,
    input logic B_N,
    input logic C,
    input logic D,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Y
);

// Y must be high when all functional inputs are low.
    check_all_low_drives_high: assert property (
        @(posedge clk)
        ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (Y == 1'b1)
    );

// Y must be low whenever any functional input is high.
    check_any_high_drives_low: assert property (
        @(posedge clk)
        ((A_N == 1'b1) || (B_N == 1'b1) || (C == 1'b1) || (D == 1'b1)) |-> (Y == 1'b0)
    );

// A high Y requires all functional inputs to be low.
    check_y_high_implies_all_low: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

// A low Y requires at least one functional input to be high.
    check_y_low_implies_any_high: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> ((A_N == 1'b1) || (B_N == 1'b1) || (C == 1'b1) || (D == 1'b1))
    );

// A_N high alone is sufficient to force Y low.
    check_a_high_forces_low: assert property (
        @(posedge clk)
        (A_N == 1'b1) |-> (Y == 1'b0)
    );

// B_N high alone is sufficient to force Y low.
    check_b_high_forces_low: assert property (
        @(posedge clk)
        (B_N == 1'b1) |-> (Y == 1'b0)
    );

// C high alone is sufficient to force Y low.
    check_c_high_forces_low: assert property (
        @(posedge clk)
        (C == 1'b1) |-> (Y == 1'b0)
    );

// D high alone is sufficient to force Y low.
    check_d_high_forces_low: assert property (
        @(posedge clk)
        (D == 1'b1) |-> (Y == 1'b0)
    );

endmodule

