sva:
module and4_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);

// X must equal the 4-input AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// When all four inputs are high, X must be high.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// If A is low, X must be low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

// If B is low, X must be low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

// If C is low, X must be low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

// If D is low, X must be low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

// A high X requires all four inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

endmodule

rtl:
module clock_gate_1 ( // Rename module name
  input CLK, EN, TE,
  output ENCLK
);

  assign ENCLK = EN ? (TE ? CLK : 1'b0) : 1'b1;

endmodule

module clock_gate_2 ( // Rename module name
  input CLK, EN, TE,
  output ENCLK
);

  assign ENCLK = EN ? (TE ? CLK : 1'b0) : 1'b1;

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

// EN low forces ENCLK high on rising-edge samples.
    check_en_low_rise_forces_high: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b1)
    );

// EN low forces ENCLK high on falling-edge samples.
    check_en_low_fall_forces_high: assert property (
        @(negedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b1)
    );

// EN high with TE low forces ENCLK low on rising-edge samples.
    check_te_low_rise_forces_low: assert property (
        @(posedge CLK) ((EN == 1'b1) && (TE == 1'b0)) |-> (ENCLK == 1'b0)
    );

// EN high with TE low forces ENCLK low on falling-edge samples.
    check_te_low_fall_forces_low: assert property (
        @(negedge CLK) ((EN == 1'b1) && (TE == 1'b0)) |-> (ENCLK == 1'b0)
    );

// EN and TE high make ENCLK follow CLK on rising-edge samples.
    check_clk_passthrough_rise: assert property (
        @(posedge CLK) ((EN == 1'b1) && (TE == 1'b1)) |-> (ENCLK == CLK)
    );

// EN and TE high make ENCLK follow CLK on falling-edge samples.
    check_clk_passthrough_fall: assert property (
        @(negedge CLK) ((EN == 1'b1) && (TE == 1'b1)) |-> (ENCLK == CLK)
    );

endmodule

module mux4x1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] S,
    input logic Y
);

// Y must match the RTL mux expression on every sampled cycle.
    check_mux_function: assert property (
        @(posedge clk)
        Y === ((S == 2'b00) ? A :
               (S == 2'b01) ? B :
               (S == 2'b10) ? C :
                              D)
    );

// Select 00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk)
        (S === 2'b00) |-> (Y === A)
    );

// Select 01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk)
        (S === 2'b01) |-> (Y === B)
    );

// Select 10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk)
        (S === 2'b10) |-> (Y === C)
    );

// Select 11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk)
        (S === 2'b11) |-> (Y === D)
    );

endmodule

rtl:
module four_way_min (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min, abcd_min;

    assign ab_min = (a < b) ? a : b;
    assign cd_min = (c < d) ? c : d;
    assign abcd_min = (ab_min < cd_min) ? ab_min : cd_min;
    assign min = abcd_min;

endmodule

sva:
module four_way_min_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] d,
    input logic [7:0] min
);

// Output must match the RTL minimum computation.
    check_output_matches_rtl: assert property (
        @(posedge clk) min == abcd_min
    );

// The reported minimum cannot exceed input a.
    check_min_le_a: assert property (
        @(posedge clk) min <= a
    );

// The reported minimum cannot exceed input b.
    check_min_le_b: assert property (
        @(posedge clk) min <= b
    );

// The reported minimum cannot exceed input c.
    check_min_le_c: assert property (
        @(posedge clk) min <= c
    );

// The reported minimum cannot exceed input d.
    check_min_le_d: assert property (
        @(posedge clk) min <= d
    );

// The reported minimum must be one of the four inputs.
    check_min_is_input_value: assert property (
        @(posedge clk) (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is no greater than all other inputs, the output must equal a.
    check_a_when_a_is_minimal: assert property (
        @(posedge clk) ((a <= b) && (a <= c) && (a <= d)) |-> (min == a)
    );

// If b is no greater than all other inputs, the output must equal b.
    check_b_when_b_is_minimal: assert property (
        @(posedge clk) ((b <= a) && (b <= c) && (b <= d)) |-> (min == b)
    );

// If c is no greater than all other inputs, the output must equal c.
    check_c_when_c_is_minimal: assert property (
        @(posedge clk) ((c <= a) && (c <= b) && (c <= d)) |-> (min == c)
    );

// If d is no greater than all other inputs, the output must equal d.
    check_d_when_d_is_minimal: assert property (
        @(posedge clk) ((d <= a) && (d <= b) && (d <= c)) |-> (min == d)
    );

endmodule

