rtl:
module carry_select_adder_32bit (A, B, Cin, S);
  input [31:0] A;
  input [31:0] B;
  input Cin;
  output [31:0] S;

  // Generate the sum and carry for each bit
  wire [31:0] sum, carry;
  genvar i;
  generate
    for (i = 0; i < 32; i = i + 1) begin: full_adder_instances
      full_adder fa (
        .A(A[i]),
        .B(B[i]),
        .Cin(Cin),
        .S(sum[i]),
        .Cout(carry[i])
      );
    end
  endgenerate

  // Select the correct sum and carry based on the input carry
  assign S = Cin ? sum : carry;

endmodule

module full_adder (A, B, Cin, S, Cout);
  input A, B, Cin;
  output S, Cout;

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (A & Cin) | (B & Cin);
endmodule

sva:
module carry_select_adder_32bit_sva (
    input logic [31:0] A,
    input logic [31:0] B,
    input logic        Cin,
    input logic [31:0] S
);

///// Functional correctness /////
    // When Cin is 1, S equals bitwise XNOR of A and B.
    check_s_eq_xnor_when_cin_high: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin) |-> (S == ~(A ^ B))
    );

// When Cin is 0, S equals bitwise AND of A and B.
    check_s_eq_and_when_cin_low: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin) |-> (S == (A & B))
    );

// When inputs are known (no X/Z), output S is known.
    check_s_known_when_inputs_known: assert property (
        @(posedge Cin) disable iff (1'b0) (!$isunknown({A,B,Cin})) |-> (!$isunknown(S))
    );

///// Useful special cases derived from the logic /////
    // With Cin=1 and A==B, S is all ones (XNOR true).
    check_allones_when_cin_high_and_a_eq_b: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == B)) |-> (S == {32{1'b1}})
    );

// With Cin=1 and A==~B, S is all zeros (XNOR false).
    check_allzeros_when_cin_high_and_a_eq_notb: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == ~B)) |-> (S == 32'b0)
    );

// With Cin=0 and B all ones, S equals A (A & all1 = A).
    check_s_eq_a_when_cin_low_and_b_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (B == {32{1'b1}})) |-> (S == A)
    );

// With Cin=0 and A all ones, S equals B (all1 & B = B).
    check_s_eq_b_when_cin_low_and_a_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (A == {32{1'b1}})) |-> (S == B)
    );

// With Cin=0 and either operand all zeros, S is all zeros.
    check_s_zero_when_cin_low_and_any_zero: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && ((A == 32'b0) || (B == 32'b0))) |-> (S == 32'b0)
    );

endmodule

rtl:
module adder4 (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S
);

    always @ (A or B) begin
        S = A + B;
        if (S > 15) begin
            S = S - 16;
        end
    end

endmodule

sva:
module adder4_sva (
    input  logic        clk,  // Sampling clock for assertions (DUT has no clock/reset)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic [3:0]  S
);

///// Functional correctness /////
    // S equals A + B modulo 16 (matches combinational RTL behavior).
    check_sum_mod16: assert property (
        @(posedge clk) S == (A + B)
    );

///// Identities /////
    // Adding zero on A leaves S equal to B.
    check_add_identity_A_zero: assert property (
        @(posedge clk) (A == 4'h0) |-> (S == B)
    );

// Adding zero on B leaves S equal to A.
    check_add_identity_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

// Zero plus zero yields zero.
    check_add_zero_zero: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> (S == 4'h0)
    );

///// Wrap-around examples (mod-16) /////
    // 15 + 1 wraps to 0.
    check_wrap_F_plus_1_A: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h1) |-> (S == 4'h0)
    );

// 1 + 15 wraps to 0.
    check_wrap_1_plus_F_B: assert property (
        @(posedge clk) (A == 4'h1 && B == 4'hF) |-> (S == 4'h0)
    );

// 15 + 15 yields 14 (mod 16).
    check_15_plus_15: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF) |-> (S == 4'hE)
    );

endmodule

