module diff_module(
  input [3:0] A,
  input [3:0] B,
  input C,
  output reg [4:0] diff
);

  always @(*) begin
    diff = A - B;
    if (C == 1'b1) begin
      diff = ~diff + 1'b1;
    end
  end

endmodule

sva:
module diff_module_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C,
    input logic [4:0] diff
);

// For any C, if A==B then diff must be 0.
    check_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A == B) |-> (diff == 5'd0)
    );

// For any C, diff==0 implies A==B.
    check_zero_implies_inputs_equal: assert property (
        @(posedge CLK) (diff == 5'd0) |-> (A == B)
    );

// When C=1 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C1: assert property (
        @(posedge CLK) (C == 1'b1 && (A != B)) |-> (diff != 5'd0)
    );

// When C=0 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C0: assert property (
        @(posedge CLK) (C == 1'b0 && (A != B)) |-> (diff != 5'd0)
    );

endmodule

rtl:
module XOR(A, B, C);
    input [7:0] A;
    input [7:0] B;
    output [7:0] C;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin
            assign C[i] = ~(A[i] & B[i]) & (A[i] | B[i]);
        end
    endgenerate
endmodule

sva:
module XOR_sva (
    input  logic        clk,   // sampling clock for combinational checks
    input  logic [7:0]  A,
    input  logic [7:0]  B,
    input  logic [7:0]  C
);

// C implements (~(A & B)) & (A | B) bitwise.
    check_functional_equation: assert property (
        @(posedge clk) disable iff (1'b0) C === ((~(A & B)) & (A | B))
    );

// C is equivalent to bitwise XOR of A and B.
    check_xor_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) C === (A ^ B)
    );

// If inputs are fully known, output must be fully known.
    check_known_inputs_imply_known_output: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown({A,B})) |-> (!$isunknown(C))
    );

// When A equals B, C must be all zeros.
    check_equal_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A === B) |-> (C === 8'h00)
    );

// When A is bitwise complement of B, C must be all ones.
    check_complement_inputs_ones: assert property (
        @(posedge clk) disable iff (1'b0) (A === ~B) |-> (C === 8'hFF)
    );

// XOR identity: A ^ 0 = A -> C equals B when A is zero.
    check_identity_A_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A === 8'h00) |-> (C === B)
    );

// XOR identity: 0 ^ B = B -> C equals A when B is zero.
    check_identity_B_zero: assert property (
        @(posedge clk) disable iff (1'b0) (B === 8'h00) |-> (C === A)
    );

// XOR with all ones: A ^ FF = ~A -> C equals ~B when A is all ones.
    check_invert_when_A_ones: assert property (
        @(posedge clk) disable iff (1'b0) (A === 8'hFF) |-> (C === ~B)
    );

// XOR with all ones: FF ^ B = ~B -> C equals ~A when B is all ones.
    check_invert_when_B_ones: assert property (
        @(posedge clk) disable iff (1'b0) (B === 8'hFF) |-> (C === ~A)
    );

// Parity consistency: parity(C) equals parity(A) XOR parity(B) when inputs known.
    check_parity_consistency: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown({A,B})) |-> ((^C) === ((^A) ^ (^B)))
    );

endmodule

rtl:
module SNPS_CLOCK_GATE_HIGH_d_ff_en_W64_0_9 (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg ENCLK_reg = 1'b0;

  always @(posedge CLK or posedge TE) begin
    if (TE == 1'b0) begin
      if (EN == 1'b1) begin
        ENCLK_reg <= #1 1'b1;
      end else begin
        ENCLK_reg <= #1 1'b0;
      end
    end
  end

  assign ENCLK = ENCLK_reg;

endmodule

sva:
module SNPS_CLOCK_GATE_HIGH_d_ff_en_W64_0_9_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK,
    // Internal signal from RTL (bind hierarchically)
    input logic ENCLK_reg
);

// When TE==0 at a clock edge, ENCLK updates next cycle to match sampled EN.
    check_update_next_cycle_match_en: assert property (
        @(posedge CLK) (TE == 1'b0) |-> ##1 (ENCLK == $past(EN))
    );

// When TE==0 and EN==1 at a clock edge, ENCLK becomes 1 on the next clock.
    check_update_next_cycle_to_one: assert property (
        @(posedge CLK) (TE == 1'b0 && EN == 1'b1) |-> ##1 (ENCLK == 1'b1)
    );

// When TE==0 and EN==0 at a clock edge, ENCLK becomes 0 on the next clock.
    check_update_next_cycle_to_zero: assert property (
        @(posedge CLK) (TE == 1'b0 && EN == 1'b0) |-> ##1 (ENCLK == 1'b0)
    );

// When TE==1 at a clock edge, ENCLK holds its value to the next clock.
    check_hold_when_te_high: assert property (
        @(posedge CLK) (TE == 1'b1) |-> ##1 (ENCLK == $past(ENCLK))
    );

endmodule

