    input logic [31:0] vote_ID_Instruction,
    input logic [31:0] vote_ID_PCAdd4,
    input logic [31:0] vote_ID_RestartPC,
    input logic vote_ID_IsBDS,
    input logic vote_ID_IsFlushed
);

// On reset, all outputs clear to zero on the next cycle.
    reset_clears_outputs: assert property (
        @(posedge clock) reset |=> (vote_ID_Instruction == 32'b0)
                            && (vote_ID_PCAdd4 == 32'b0)
                            && (vote_ID_RestartPC == 32'b0)
                            && (vote_ID_IsBDS == 1'b0)
                            && (vote_ID_IsFlushed == 1'b0)
    );

// When ID_Stall is asserted, data fields capture from ID_* on the next cycle.
    id_stall_captures_id_data: assert property (
        @(posedge clock) disable iff (reset)
            ID_Stall |=> (vote_ID_Instruction == $past(ID_Instruction))
                      && (vote_ID_PCAdd4    == $past(ID_PCAdd4))
                      && (vote_ID_RestartPC == $past(ID_RestartPC))
    );

// When !ID_Stall and IF_Stall or IF_Flush, instruction and PCAdd4 zero on next cycle.
    zero_if_fields_on_if_stall_or_flush: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == 32'b0)
                                                  && (vote_ID_PCAdd4 == 32'b0)
    );

// When !ID_Stall and no IF_Stall/Flush, instruction and PCAdd4 pass through from IF_*.
    pass_if_fields_when_no_if_controls: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == $past(IF_Instruction))
                                                   && (vote_ID_PCAdd4    == $past(IF_PCAdd4))
    );

// When !ID_Stall and (ID_IsFlushed or IF_IsBDS), RestartPC comes from ID_RestartPC.
    restartpc_selects_id_on_flush_or_bds: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(ID_RestartPC))
    );

// When !ID_Stall and not (ID_IsFlushed or IF_IsBDS), RestartPC comes from IF_PC.
    restartpc_selects_if_on_normal_flow: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(IF_PC))
    );

// vote_ID_IsBDS always reflects prior-cycle ID_IsBDS (outside reset).
    flags_follow_id_isbds: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsBDS == $past(ID_IsBDS))
    );

// vote_ID_IsFlushed always reflects prior-cycle ID_IsFlushed (outside reset).
    flags_follow_id_isflushed: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsFlushed == $past(ID_IsFlushed))
    );

endmodule

module counter_with_load_reset_sva (
    input  logic [3:0] DATA_IN,
    input  logic       LOAD,
    input  logic       CLK,
    input  logic       RESET,
    input  logic [3:0] COUNT
);

///// Reset behavior /////
    // When RESET is asserted low, COUNT must be 0.
    check_reset_drives_zero: assert property (
        @(posedge CLK) (!RESET) |-> (COUNT == 4'd0)
    );

///// Next-state behavior /////
    // General next-state: after a non-reset cycle, COUNT matches LOAD/Data/Inc from previous cycle.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) |-> COUNT == ($past(LOAD) ? $past(DATA_IN) : (($past(COUNT) + 4'd1) & 4'hF))
    );

// LOAD=1 loads DATA_IN on the next cycle.
    check_load_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) |-> (COUNT == $past(DATA_IN))
    );

// LOAD=0 increments COUNT by 1 modulo 16 on the next cycle.
    check_increment_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT == (($past(COUNT) + 4'd1) & 4'hF))
    );

// LOAD=0 causes COUNT to change (it cannot hold its value).
    check_increment_changes_value: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT != $past(COUNT))
    );

// With LOAD=0 and COUNT at 15, next COUNT wraps to 0.
    check_wrap_on_max_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) && ($past(COUNT) == 4'hF) |-> (COUNT == 4'h0)
    );

// If LOAD=1, the load path has priority over increment (distinct from +1 result).
    check_load_priority_over_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) &&
            ($past(DATA_IN) != (($past(COUNT) + 4'd1) & 4'hF)) |-> (COUNT != (($past(COUNT) + 4'd1) & 4'hF))
    );

// Two consecutive cycles with LOAD=0 increment COUNT by 2 modulo 16.
    check_two_cycle_increment_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && !$past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(COUNT,2) + 4'd2) & 4'hF)
    );

// LOAD followed by no LOAD results in DATA_IN+1 on the second cycle (modulo 16).
    check_load_then_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && $past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(DATA_IN,2) + 4'd1) & 4'hF)
    );

endmodule

rtl:
module max_module (
    input wire [3:0] priority_enc_out,
    input wire [3:0] comb_circuit_out,
    output reg [3:0] max_out
);

    // Comparator functional module
    always @(*) begin
        if (priority_enc_out > comb_circuit_out) begin
            max_out = priority_enc_out;
        end else begin
            max_out = comb_circuit_out;
        end
    end

endmodule

sva:
module max_module_sva (
    input logic clk,
    input logic [3:0] priority_enc_out,
    input logic [3:0] comb_circuit_out,
    input logic [3:0] max_out
);

// Output equals the max of the two inputs (unsigned compare).
    check_max_function: assert property (
        @(posedge clk) max_out == (priority_enc_out > comb_circuit_out ? priority_enc_out : comb_circuit_out)
    );

// Output is always equal to one of the two inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk) (max_out == priority_enc_out) || (max_out == comb_circuit_out)
    );

// When priority_enc_out > comb_circuit_out, select priority_enc_out.
    check_select_priority_when_greater: assert property (
        @(posedge clk) (priority_enc_out > comb_circuit_out) |-> (max_out == priority_enc_out)
    );

// When priority_enc_out <= comb_circuit_out, select comb_circuit_out.
    check_select_comb_when_not_greater: assert property (
        @(posedge clk) (priority_enc_out <= comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

// On tie, output equals comb_circuit_out.
    check_tie_selects_comb: assert property (
        @(posedge clk) (priority_enc_out == comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

// Output is not less than priority_enc_out.
    check_max_ge_priority: assert property (
        @(posedge clk) max_out >= priority_enc_out
    );

// Output is not less than comb_circuit_out.
    check_max_ge_comb: assert property (
        @(posedge clk) max_out >= comb_circuit_out
    );

// If output equals comb_circuit_out, then comb_circuit_out >= priority_enc_out.
    check_out_eq_comb_implies_comb_ge_priority: assert property (
        @(posedge clk) (max_out == comb_circuit_out) |-> (comb_circuit_out >= priority_enc_out)
    );

endmodule

rtl:
module and_gate(
    input a, 
    input b,
    output reg out
);

    always @(*) begin
        out = (a & b) ? 1'b1 : 1'b0;
    end

endmodule

sva:
module and_gate_sva (
    input logic clk,     // sampling clock (environment-provided)
    input logic a,
    input logic b,
    input logic out
);

// Output equals logical AND of inputs (4-state aware).
    check_out_equals_and: assert property (
        @(posedge clk) out === (a & b)
    );

// When both inputs are 1, out must be 1.
    check_out_one_when_both_one: assert property (
        @(posedge clk) (a === 1'b1 && b === 1'b1) |-> (out === 1'b1)
    );

// When any input is 0, out must be 0.
    check_out_zero_when_any_zero: assert property (
        @(posedge clk) ((a === 1'b0) || (b === 1'b0)) |-> (out === 1'b0)
    );

// Out can be 1 only if both inputs are 1.
    check_out_one_implies_inputs_one: assert property (
        @(posedge clk) (out === 1'b1) |-> (a === 1'b1 && b === 1'b1)
    );

// Rising edge on out only when both inputs are high.
    check_out_rise_requires_both_high: assert property (
        @(posedge clk) $rose(out) |-> (a === 1'b1 && b === 1'b1)
    );

// Falling edge on out only when any input is low.
    check_out_fall_requires_any_low: assert property (
        @(posedge clk) $fell(out) |-> ((a === 1'b0) || (b === 1'b0))
    );

// With known inputs, out is known and equals a & b.
    check_out_known_when_inputs_known: assert property (
        @(posedge clk) ((a inside {1'b0,1'b1}) && (b inside {1'b0,1'b1})) |-> ((out inside {1'b0,1'b1}) && (out === (a & b)))
    );

// Unknown out implies at least one input is unknown.
    check_x_out_implies_x_input: assert property (
        @(posedge clk) (!(out inside {1'b0,1'b1})) |-> ( !(a inside {1'b0,1'b1}) || !(b inside {1'b0,1'b1}) )
    );

endmodule

rtl:
module mux_2to1 (
    input A,
    input B,
    input SEL,
    output Y
);

    assign Y = (SEL == 0) ? A : B;

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic SEL,
    input logic Y
);

// Y must equal the selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((SEL == 1'b0) ? A : B)
    );

// When SEL is 0, Y must equal A.
    check_sel_zero_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0) |-> (Y == A)
    );

// When SEL is 1, Y must equal B.
    check_sel_one_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1) |-> (Y == B)
    );

// Y must always equal one of the inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == A) || (Y == B)
    );

// If inputs are equal, Y must equal that common value.
    check_equal_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Y == A)
    );

// If inputs differ and Y equals A, SEL must be 0.
    check_select_infers_zero_when_outputs_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == A) |-> (SEL == 1'b0)
    );

// If inputs differ and Y equals B, SEL must be 1.
    check_select_infers_one_when_outputs_B: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == B) |-> (SEL == 1'b1)
    );

// With SEL=0, Y can equal B only if A equals B.
    check_no_bypass_when_sel_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0 && (Y == B)) |-> (A == B)
    );

// With SEL=1, Y can equal A only if A equals B.
    check_no_bypass_when_sel_one: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1 && (Y == A)) |-> (A == B)
    );

endmodule

rtl:
module two_bit_output(clk, b, so);
input clk;
input [3:0] b;
output [1:0] so;
reg [1:0] so;

	always @(posedge clk)
		case (b)
			4'b0000, 4'b0001, 4'b0010: so = 2'b00;
			4'b0011, 4'b0100: so = 2'b01;
			4'b0101, 4'b0110: so = 2'b10;
			4'b0111: so = 2'b11;
			default: so = 2'b00;
		endcase

endmodule

sva:
module two_bit_output_sva (
    input logic clk,
    input logic [3:0] b,
    input logic [1:0] so
);

// Next cycle so=00 when b is 0,1,2.
    map_b_0_1_2_to_so_00: assert property (
        @(posedge clk) (b inside {4'd0,4'd1,4'd2}) |=> (so == 2'b00)
    );

// Next cycle so=01 when b is 3 or 4.
    map_b_3_4_to_so_01: assert property (
        @(posedge clk) (b inside {4'd3,4'd4}) |=> (so == 2'b01)
    );

// Next cycle so=10 when b is 5 or 6.
    map_b_5_6_to_so_10: assert property (
        @(posedge clk) (b inside {4'd5,4'd6}) |=> (so == 2'b10)
    );

// Next cycle so=11 when b is 7.
    map_b_7_to_so_11: assert property (
        @(posedge clk) (b == 4'd7) |=> (so == 2'b11)
    );

// Next cycle so=00 for default cases b=8..15.
    map_b_8_to_15_default_to_so_00: assert property (
        @(posedge clk) (b inside {[4'd8:4'd15]}) |=> (so == 2'b00)
    );

// For b=3..7, next cycle so is never 00.
    not_00_for_b_3_to_7: assert property (
        @(posedge clk) (b inside {[4'd3:4'd7]}) |=> (so != 2'b00)
    );

// Only b=3 or 4 produce next cycle so=01.
    only_3_4_give_01: assert property (
        @(posedge clk) (!(b inside {4'd3,4'd4})) |=> (so != 2'b01)
    );

// Only b=5 or 6 produce next cycle so=10.
    only_5_6_give_10: assert property (
        @(posedge clk) (!(b inside {4'd5,4'd6})) |=> (so != 2'b10)
    );

// Only b=7 produces next cycle so=11.
    only_7_gives_11: assert property (
        @(posedge clk) (b != 4'd7) |=> (so != 2'b11)
    );

endmodule

rtl:
module nand4 (
    input A,
    input B,
    input C,
    input D,
    output Y
);

wire AB, CD, ABCD;
not (AB, A & B);
not (CD, C & D);
not (ABCD, AB & CD);
not (Y, ABCD);

endmodule

sva:
module nand4_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

// Y equals (~(A & B)) & (~(C & D)).
    check_y_eq_nands_and_form: assert property (
        @(posedge CLK) Y == ((~(A & B)) & (~(C & D)))
    );

// Y equals ~((A & B) | (C & D)) by De Morgan.
    check_y_eq_demorgan_or_form: assert property (
        @(posedge CLK) Y == ~( (A & B) | (C & D) )
    );

// If A and B are both 1, Y must be 0.
    check_ab_high_forces_y_low: assert property (
        @(posedge CLK) (A & B) |-> (Y == 1'b0)
    );

// If C and D are both 1, Y must be 0.
    check_cd_high_forces_y_low: assert property (
        @(posedge CLK) (C & D) |-> (Y == 1'b0)
    );

// If neither A&B nor C&D is 1, Y must be 1.
    check_no_pair_and_implies_y_high: assert property (
        @(posedge CLK) (!(A & B) && !(C & D)) |-> (Y == 1'b1)
    );

// If Y is 1, then neither A&B nor C&D is 1.
    check_y_high_implies_no_pair_and: assert property (
        @(posedge CLK) Y |-> (!(A & B) && !(C & D))
    );

// If Y is 0, then at least one of A&B or C&D is 1.
    check_y_low_implies_some_pair_and: assert property (
        @(posedge CLK) (!Y) |-> ((A & B) || (C & D))
    );

endmodule

rtl:
module priority_encoder (
    input [7:0] I,
    output reg EN,
    output reg V,
    output reg [2:0] Q
);

    parameter WIDTH = 8;
    integer i;

    always @(*) begin
        if (|I) begin
            EN = 1;
            V = (|I) & (~&I);
            for (i = 0; i < WIDTH; i = i + 1) begin
                if (I[i]) begin
                    Q = i + 1'b1;
                end
            end
        end
        else begin
            EN = 0;
            V = 0;
            Q = 0;
        end
    end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [7:0] I,
    input logic EN,
    input logic V,
    input logic [2:0] Q
);

// When I is zero, outputs are all zero.
    check_outputs_when_I_zero: assert property (
        @(posedge clk) (I == 8'b0) |-> (EN == 1'b0 && V == 1'b0 && Q == 3'b000)
    );

// If bit 7 is set, Q wraps to 0 due to i+1 truncation to 3 bits.
    check_q_zero_when_bit7_set: assert property (
        @(posedge clk) I[7] |-> (Q == 3'b000)
    );

endmodule

rtl:
module up_down_counter (
    input clk,
    input reset,
    input load,
    input up_down,
    input [3:0] data_in,
    output reg [3:0] count_out
);

    always @(posedge clk) begin
        if (reset) begin
            count_out <= 4'b0;
        end else if (load) begin
            count_out <= data_in;
        end else if (up_down) begin
            count_out <= count_out + 1;
        end else begin
            count_out <= count_out - 1;
        end
    end

endmodule

sva:
module up_down_counter_sva (
    input logic clk,
    input logic reset,       // active-high synchronous reset
    input logic load,
    input logic up_down,
    input logic [3:0] data_in,
    input logic [3:0] count_out
);

///// Reset behavior /////
    // Synchronous reset drives count_out to zero on the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'b0000)
    );

///// Load behavior /////
    // When load is asserted (no reset), next count_out equals data_in.
    load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |=> (count_out == $past(data_in))
    );

// Load has priority over up/down counting when both are asserted.
    load_overrides_updown: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (count_out == $past(data_in))
    );

///// Counting behavior /////
    // When counting up (load=0, up_down=1), next count_out = previous + 1 (mod 16).
    count_up_when_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count_out == ($past(count_out) + 4'd1))
    );

// When counting down (load=0, up_down=0), next count_out = previous - 1 (mod 16).
    count_down_when_not_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count_out == ($past(count_out) - 4'd1))
    );

///// Wrap-around behavior /////
    // Up-count wraps from 15 to 0.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// Down-count wraps from 0 to 15.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count_out == 4'h0)) |=> (count_out == 4'hF)
    );

endmodule

rtl:
module my_nor (
    input a,
    input b,
    output y
);

    assign y = ~(a | b);

endmodule

sva:
module my_nor_assert (
    input logic clk,
    input logic a,
    input logic b,
    input logic y
);

///// NOR function checks /////
    // y must equal NOR of a and b.
    check_y_is_nor: assert property (
        @(posedge clk) y == ~(a | b)
    );

// If a is 1, y must be 0.
    check_y_zero_if_a_one: assert property (
        @(posedge clk) (a == 1'b1) |-> (y == 1'b0)
    );

// If b is 1, y must be 0.
    check_y_zero_if_b_one: assert property (
        @(posedge clk) (b == 1'b1) |-> (y == 1'b0)
    );

// If both a and b are 0, y must be 1.
    check_y_one_if_both_zero: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b0) |-> (y == 1'b1)
    );

// If y is 1, both inputs must be 0.
    check_inputs_zero_if_y_one: assert property (
        @(posedge clk) (y == 1'b1) |-> (a == 1'b0 && b == 1'b0)
    );

// If y is 0, at least one input must be 1.
    check_some_input_one_if_y_zero: assert property (
        @(posedge clk) (y == 1'b0) |-> (a == 1'b1 || b == 1'b1)
    );

endmodule

module updown_counter_sva (
    input logic clk,
    input logic U_D,
    input logic [3:0] Q
);

// Q must change every cycle (never holds its value).
    check_q_always_changes: assert property (
        @(posedge clk) 1'b1 |=> $changed(Q)
    );

// The magnitude of the step each cycle is exactly 1 (mod 16).
    check_delta_one: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) || (Q == $past(Q) - 4'd1) )
    );

// Exactly one of +1 or -1 delta holds each cycle.
    check_delta_exclusive: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) != (Q == $past(Q) - 4'd1) )
    );

// LSB toggles every cycle due to +/-1 operation.
    check_lsb_toggle: assert property (
        @(posedge clk) 1'b1 |=> ( Q[0] != $past(Q[0]) )
    );

endmodule

rtl:
module mux_2to1 (
  input A0,
  input A1,
  input S,
  output X
);

  // select A0 if S is 0, A1 if S is 1
  assign X = (!S) ? A0 : A1;

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic S,
    input logic X
);

// X equals A0 when S=0, else A1 (functional equivalence).
    check_mux_truth_table: assert property (
        @(posedge clk) X == ((S == 1'b0) ? A0 : A1)
    );

// When S=0 and A0 changes (others stable), X must equal A0.
    check_selected_change_reflected_S0: assert property (
        @(posedge clk) (S == 1'b0) && $changed(A0) && $stable(A1) && $stable(S) |-> (X == A0)
    );

// When S=1 and A1 changes (others stable), X must equal A1.
    check_selected_change_reflected_S1: assert property (
        @(posedge clk) (S == 1'b1) && $changed(A1) && $stable(A0) && $stable(S) |-> (X == A1)
    );

// On S rising edge, X must equal A1.
    check_select_rise_routes_A1: assert property (
        @(posedge clk) $rose(S) |-> (X == A1)
    );

// On S falling edge, X must equal A0.
    check_select_fall_routes_A0: assert property (
        @(posedge clk) $fell(S) |-> (X == A0)
    );

// If A0 equals A1, X must equal that value regardless of S.
    check_equal_inputs_drive_x: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

endmodule

module pg_to_PG_sva (
    input logic clk,
    input logic [15:0] p,
    input logic [15:0] g,
    input logic [3:0] bp,
    input logic [3:0] bg
);

///// Block-generate definitions /////
    // bg[0] equals g[3] | p[3]&g[2] | p[3]&p[2]&g[1] | p[3]&p[2]&p[1]&g[0]
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3]
                               | (p[3] & g[2])
                               | (p[3] & p[2] & g[1])
                               | (p[3] & p[2] & p[1] & g[0]) )
    );

// bg[1] equals g[7] | p[7]&g[6] | p[7]&p[6]&g[5] | p[7]&p[6]&p[5]&g[4]
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7]
                               | (p[7] & g[6])
                               | (p[7] & p[6] & g[5])
                               | (p[7] & p[6] & p[5] & g[4]) )
    );

// bg[2] equals g[11] | p[11]&g[10] | p[11]&p[10]&g[9] | p[11]&p[10]&p[9]&g[8]
    check_bg2_definition: assert property (
        @(posedge clk) bg[2] == ( g[11]
                               | (p[11] & g[10])
                               | (p[11] & p[10] & g[9])
                               | (p[11] & p[10] & p[9] & g[8]) )
    );

// bg[3] equals g[15] | p[15]&g[14] | p[15]&p[14]&g[13] | p[15]&p[14]&p[13]&g[12]
    check_bg3_definition: assert property (
        @(posedge clk) bg[3] == ( g[15]
                               | (p[15] & g[14])
                               | (p[15] & p[14] & g[13])
                               | (p[15] & p[14] & p[13] & g[12]) )
    );

///// Block-propagate definitions /////
    // bp[0] equals p[3]&p[2]&p[1]&p[0]
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );

// bp[1] equals p[7]&p[6]&p[5]&p[4]
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );

// bp[2] equals p[11]&p[10]&p[9]&p[8]
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );

// bp[3] equals p[15]&p[14]&p[13]&p[12]
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

///// Necessary conditions for block-generate /////
    // If bg[0] is 1, at least one g in [3:0] is 1.
    check_bg0_implies_some_g: assert property (
        @(posedge clk) bg[0] |-> (g[3] || g[2] || g[1] || g[0])
    );

// If bg[1] is 1, at least one g in [7:4] is 1.
    check_bg1_implies_some_g: assert property (
        @(posedge clk) bg[1] |-> (g[7] || g[6] || g[5] || g[4])
    );

// If bg[2] is 1, at least one g in [11:8] is 1.
    check_bg2_implies_some_g: assert property (
        @(posedge clk) bg[2] |-> (g[11] || g[10] || g[9] || g[8])
    );

// If bg[3] is 1, at least one g in [15:12] is 1.
    check_bg3_implies_some_g: assert property (
        @(posedge clk) bg[3] |-> (g[15] || g[14] || g[13] || g[12])
    );

endmodule

rtl:
module binary_counter(
    input clk,
    input rst,
    output reg [3:0] count
);

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,          // active-low reset
    input logic [3:0] count
);

// When reset is asserted (low), count must be 0 at each clock edge.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst) |-> (count == 4'h0)
    );

// With reset deasserted in consecutive cycles, count increments by 1 each cycle (mod 16).
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count == $past(count) + 4'd1)
    );

// When previous value was 15 and still enabled, next value wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// Over two consecutive enabled cycles, count advances by 2 (mod 16).
    check_two_step_increment: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst,2) && $past(rst)) |-> (count == $past(count,2) + 4'd2)
    );

// On reset release ($rose), the next enabled cycle increments from the reset value.
    check_increment_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == $past(count) + 4'd1)
    );

// On reset assertion ($fell), count is driven to 0 at that clock edge.
    check_zero_on_reset_assertion: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'h0)
    );

// When enabled and not wrapping, next value cannot be 0.
    check_nonzero_when_not_wrapping: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) != 4'hF)) |-> (count != 4'h0)
    );

endmodule

module my_flip_flop_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic DE,
    input logic VPWR,
    input logic VGND
);

// With DE=1 now, on the next edge Q equals the current D.
    check_capture_next_cycle_on_current_enable: assert property (
        @(posedge CLK) DE |-> ##1 (Q == $past(D))
    );

endmodule

rtl:
module abs_difference (
    CLOCK,
    RESET,
    x,
    y,
    DIFF
);

    input CLOCK, RESET;
    input [11:0] x, y;
    output reg [11:0] DIFF;

    always @ (posedge CLOCK or posedge RESET) begin
        if (RESET) begin
            DIFF <= 0;
        end else begin
            DIFF <= (x > y) ? x - y : y - x;
        end
    end

endmodule

sva:
module abs_difference_sva (
    input logic CLOCK,
    input logic RESET,
    input logic [11:0] x,
    input logic [11:0] y,
    input logic [11:0] DIFF
);

// Clock: CLOCK (posedge). Reset: RESET (active-high, asynchronous).
    // Logic: Sequential register computing absolute difference; DIFF cleared to 0 on RESET.

    // DIFF must be 0 whenever RESET is asserted at the clock edge.
    reset_forces_zero: assert property (
        @(posedge CLOCK) RESET |-> (DIFF == 12'd0)
    );

endmodule

rtl:
module add_sub_comp (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output reg out
);

    reg [3:0] result;
    wire [1:0] comp_out;

    two_bit_comparator comp (
        .a(a),       // Fix the a and b inputs order
        .b(b),   // Fix the a and b inputs order
        .out(comp_out)
    );

    adder_subtractor add_sub (
        .a(a),
        .b(b),
        .sub(sub),
        .result(result)
    );

    always @(*) begin
        case (comp_out)
            2'b00: out <= 1;
            default: out <= 0;
        endcase
    end

endmodule
module two_bit_comparator (
    input [3:0] a,
    input [3:0] b,
    output reg [1:0] out
);

    always @(*) begin
        if (a > b) begin
            out = 2'b10;
        end else if (a == b) begin
            out = 2'b01;
        end else begin
            out = 2'b00;
        end
    end

endmodule
module adder_subtractor (
    input [3:0] a,
    input [3:0] b,
    input sub,
    output reg [3:0] result
);

    always @(*) begin
        if (sub) begin
            result = a - b;
        end else begin
            result = a + b;
        end
    end

endmodule

sva:
module add_sub_comp_sva (
    input logic clk,           // Sampling clock for assertions (DUT has no clock/reset)
    input logic [3:0] a,       // DUT input
    input logic [3:0] b,       // DUT input
    input logic sub,           // DUT input (does not affect out)
    input logic out            // DUT output: 1 when a < b, else 0
);

// Analysis: No clock/reset in RTL; pure combinational. out=1 iff a<b; sub does not affect out.

    ///// Functional equivalence /////
    // out must reflect comparator result: out == (a < b).
    check_out_equals_less: assert property (
        @(posedge clk) out == (a < b)
    );

///// Case-specific behavior /////
    // When a < b, out is 1.
    check_out_one_when_less: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b1)
    );

// When a >= b, out is 0.
    check_out_zero_when_ge: assert property (
        @(posedge clk) (a >= b) |-> (out == 1'b0)
    );

endmodule

