module binary_counter_4bit(
    input clk,
    input rst_n,
    output reg [3:0] count
);

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
        if (count == 4'b1111) begin
            count <= 4'b0;
        end
    end
end

