module and_or_sva (
    input logic CLK,  // external clock for sampling assertions
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

// DUT is purely combinational with no reset; use disable iff (1'b0).

    // Y equals A|B|D (absorbing (A&B&C) into A|B).
    check_y_function_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y === (A | B | D)
    );

// Y must be 1 whenever D is 1.
    check_y_high_if_d_high: assert property (
        @(posedge CLK) disable iff (1'b0) D |-> (Y === 1'b1)
    );

// Y must be 1 whenever A is 1.
    check_y_high_if_a_high: assert property (
        @(posedge CLK) disable iff (1'b0) A |-> (Y === 1'b1)
    );

// Y must be 1 whenever B is 1.
    check_y_high_if_b_high: assert property (
        @(posedge CLK) disable iff (1'b0) B |-> (Y === 1'b1)
    );

// With D==0, Y equals A|B.
    check_y_eq_a_or_b_when_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (D === 1'b0) |-> (Y === (A | B))
    );

// With A==0 and B==0, Y equals D.
    check_y_eq_d_when_a_b_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (B === 1'b0) |-> (Y === D)
    );

// With B==0 and D==0, Y equals A.
    check_y_eq_a_when_b_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (B === 1'b0) && (D === 1'b0) |-> (Y === A)
    );

// With A==0 and D==0, Y equals B.
    check_y_eq_b_when_a_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (D === 1'b0) |-> (Y === B)
    );

// Y rising requires at least one of A,B,D to be 1.
    check_y_rise_requires_input_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(Y) |-> (A || B || D)
    );

// Y falling requires A,B,D all 0.
    check_y_fall_requires_inputs_low: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(Y) |-> (!A && !B && !D)
    );

endmodule

rtl:
module comparator (
  input [7:0] in1,
  input [7:0] in2,
  output reg out_eq,
  output reg out_gt,
  output reg out_lt
);

  always @(*) begin
    if (in1 == in2) begin
      out_eq = 1;
      out_gt = 0;
      out_lt = 0;
    end else if (in1 > in2) begin
      out_eq = 0;
      out_gt = 1;
      out_lt = 0;
    end else begin
      out_eq = 0;
      out_gt = 0;
      out_lt = 1;
    end
  end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic out_eq,
    input logic out_gt,
    input logic out_lt
);

// Outputs exactly match the comparator functions of inputs.
    check_functional_mapping: assert property (
        @(posedge clk) (out_eq == (in1 == in2)) && (out_gt == (in1 > in2)) && (out_lt == (in1 < in2))
    );

// Exactly one output is HIGH at any time (one-hot).
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({out_eq, out_gt, out_lt})
    );

// Outputs are never all zero.
    check_outputs_not_all_zero: assert property (
        @(posedge clk) (out_eq || out_gt || out_lt)
    );

// When inputs are equal, only out_eq is HIGH.
    check_eq_when_equal: assert property (
        @(posedge clk) (in1 == in2) |-> (out_eq && !out_gt && !out_lt)
    );

// When in1 > in2, only out_gt is HIGH.
    check_gt_when_greater: assert property (
        @(posedge clk) (in1 > in2) |-> (!out_eq && out_gt && !out_lt)
    );

// When in1 < in2, only out_lt is HIGH.
    check_lt_when_less: assert property (
        @(posedge clk) (in1 < in2) |-> (!out_eq && !out_gt && out_lt)
    );

// If out_eq is HIGH, inputs must be equal.
    check_eq_implies_equal: assert property (
        @(posedge clk) out_eq |-> (in1 == in2)
    );

// If out_gt is HIGH, in1 must be greater than in2.
    check_gt_implies_greater: assert property (
        @(posedge clk) out_gt |-> (in1 > in2)
    );

// If out_lt is HIGH, in1 must be less than in2.
    check_lt_implies_less: assert property (
        @(posedge clk) out_lt |-> (in1 < in2)
    );

// No two outputs can be HIGH simultaneously (mutual exclusion).
    check_mutex_pairs: assert property (
        @(posedge clk) !(out_eq && out_gt) && !(out_eq && out_lt) && !(out_gt && out_lt)
    );

endmodule

