module nios_system_switches (
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  9: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  9: 0] data_in;
  wire    [  9: 0] read_mux_out;
  reg     [ 31: 0] readdata;

  // Select the data to be read from the input port
  assign read_mux_out = {10 {(address == 2'b00)}} & in_port;

  // Enable the clock signal
  assign clk_en = 1;

  // Assign the selected data to the data_in signal
  assign data_in = read_mux_out;

  // Update the readdata signal on the rising edge of the clock signal
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | data_in};
    end
  end

endmodule

sva:
module nios_system_switches_sva (
    input logic        clk,
    input logic        reset_n,    // active-low, async in RTL
    input logic [1:0]  address,
    input logic [9:0]  in_port,
    input logic [31:0] readdata
);

// Clock: clk (posedge). Logic: combinational mux into a registered 32-bit output.

    // During reset, readdata must be cleared to 0.
    reset_clears_readdata: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'd0)
    );

// After one cycle out of reset, upper 22 bits are always zero (zero-extension).
    upper_bits_zero_postreset: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[31:10] == 22'd0)
    );

// When prior address was not 0, the full word must be zero.
    full_word_zero_when_addr_not00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) != 2'b00) |-> (readdata == 32'd0)
    );

// Nonzero LSBs imply prior address selected the port (address==0).
    lsb_nonzero_implies_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (readdata[9:0] != 10'd0) |-> ($past(address) == 2'b00)
    );

endmodule

rtl:
module swap_first_last_16_bits (
  input clk,
  input reset,
  input [31:0] in_vec,
  input control,
  output reg [31:0] out_vec
);

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      out_vec <= 0;
    end else begin
      if (control) begin
        out_vec[15:0] <= in_vec[31:16];
        out_vec[31:16] <= in_vec[15:0];
      end else begin
        out_vec <= in_vec;
      end
    end
  end

endmodule

sva:
module swap_first_last_16_bits_sva (
  input logic clk,
  input logic reset,
  input logic [31:0] in_vec,
  input logic control,
  input logic [31:0] out_vec
);

// While reset is HIGH, out_vec must be zero.
  reset_clears_outvec: assert property (
    @(posedge clk) reset |-> (out_vec == 32'd0)
  );

// Next-cycle out_vec equals previous in_vec or its 16-bit-swapped version based on previous control.
  deterministic_next_state: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec == ($past(control) ? {$past(in_vec[15:0]), $past(in_vec[31:16])} : $past(in_vec)))
  );

// Next-cycle upper 16 bits reflect previous control selection (swap or passthrough).
  next_upper_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[31:16] == ($past(control) ? $past(in_vec[15:0]) : $past(in_vec[31:16])))
  );

// Next-cycle lower 16 bits reflect previous control selection (swap or passthrough).
  next_lower_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[15:0] == ($past(control) ? $past(in_vec[31:16]) : $past(in_vec[15:0])))
  );

// If control is LOW, next-cycle out_vec passes through previous in_vec.
  passthrough_when_control0: assert property (
    @(posedge clk) disable iff (reset)
      (!control) |=> (out_vec == $past(in_vec))
  );

// If control is HIGH, next-cycle out_vec swaps previous in_vec upper/lower 16 bits.
  swap_when_control1: assert property (
    @(posedge clk) disable iff (reset)
      (control) |=> ((out_vec[31:16] == $past(in_vec[15:0])) && (out_vec[15:0] == $past(in_vec[31:16])))
  );

endmodule

module d_ff_en_sva (
    input logic D,
    input logic EN,
    input logic CLK,
    input logic Q
);

///// Functional next-state behavior /////
    // Next cycle Q equals (EN ? D : Q) from the previous cycle.
    check_next_state_equation: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ($past(EN) ? $past(D) : $past(Q)))
    );

///// Update behavior /////
    // When EN is 1, Q on the next cycle equals D from this cycle.
    check_update_on_enable: assert property (
        @(posedge CLK) EN |=> (Q == $past(D))
    );

// When EN is 0, Q holds its previous value.
    check_hold_on_disable: assert property (
        @(posedge CLK) !EN |=> (Q == $past(Q))
    );

///// Multi-cycle consistency /////
    // If EN=0 for two consecutive cycles, Q two cycles later equals its value two cycles ago.
    check_two_cycle_hold_when_disabled: assert property (
        @(posedge CLK) !EN ##1 !EN |=> (Q == $past(Q,2))
    );

// If EN=1 for two consecutive cycles, Q two cycles later equals D from one cycle ago.
    check_two_cycle_enable_latest_data: assert property (
        @(posedge CLK) EN ##1 EN |=> (Q == $past(D,1))
    );

endmodule

