rtl:
module spll (
	areset,
	inclk0,
	c0,
	c1,
	locked);

	input	  areset;
	input	  inclk0;
	output	  c0;
	output	  c1;
	output	  locked;

	reg c0_reg;
	reg c1_reg;
	reg locked_reg;

	always @(posedge inclk0 or negedge areset) begin
		if (!areset) begin
			c0_reg <= 1'b0;
			c1_reg <= 1'b1;
			locked_reg <= 1'b0;
		end else begin
			if (c0_reg & c1_reg) begin
				c0_reg <= 1'b1;
				c1_reg <= 1'b0;
				locked_reg <= 1'b1;
			end else begin
				c0_reg <= c1_reg;
				c1_reg <= ~c0_reg;
				locked_reg <= 1'b0;
			end
		end
	end

	assign c0 = c0_reg;
	assign c1 = c1_reg;
	assign locked = locked_reg;

endmodule

sva:
module spll_sva (
    input logic areset,
    input logic inclk0,
    input logic c0,
    input logic c1,
    input logic locked
);

///// Reset behavior /////
    // While reset is asserted (low), outputs drive c0=0, c1=1, locked=0.
    check_reset_values: assert property (
        @(posedge inclk0) !areset |-> (c0 == 1'b0) && (c1 == 1'b1) && (locked == 1'b0)
    );

///// Locked relation /////
    // locked equals c0 AND NOT c1 every active cycle.
    check_locked_matches_outputs: assert property (
        @(posedge inclk0) disable iff (!areset) locked == (c0 & ~c1)
    );

///// State transitions /////
    // From state 00, next state is 01 and locked=0.
    check_transition_from_00: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b1 && locked == 1'b0)
    );

// From state 01, next state is 11 and locked=0.
    check_transition_from_01: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b1 && locked == 1'b0)
    );

// From state 11, next state is 10 and locked=1.
    check_transition_from_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b0 && locked == 1'b1)
    );

// From state 10, next state is 00 and locked=0.
    check_transition_from_10: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b0 && locked == 1'b0)
    );

///// Locked pulse behavior /////
    // locked cannot stay HIGH for two consecutive cycles.
    check_locked_single_cycle_pulse: assert property (
        @(posedge inclk0) disable iff (!areset) locked |=> !locked
    );

///// Post-reset sequencing /////
    // On the first cycle after reset deasserts, state is 11 with locked=0.
    check_first_cycle_after_reset_deassert: assert property (
        @(posedge inclk0) disable iff (!areset) $rose(areset) |-> (c0 == 1'b1) && (c1 == 1'b1) && (locked == 1'b0)
    );

///// Locked next-state when not in 11 /////
    // If current state is not 11, next locked is 0.
    check_locked_next_zero_when_not_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            !(c0 && c1) |=> (locked == 1'b0)
    );

endmodule

rtl:
module scan_chain_interface (
    input ctu_tst_pre_grst_l,
    input arst_l,
    input global_shift_enable,
    input ctu_tst_scan_disable,
    input ctu_tst_scanmode,
    input ctu_tst_macrotest,
    input ctu_tst_short_chain,
    input long_chain_so_0,
    input short_chain_so_0,
    input long_chain_so_1,
    input short_chain_so_1,
    input long_chain_so_2,
    input short_chain_so_2,
    output mux_drive_disable,
    output mem_write_disable,
    output sehold,
    output se,
    output testmode_l,
    output mem_bypass,
    output so_0,
    output so_1,
    output so_2
);

    wire pin_based_scan;
    wire short_chain_en;
    wire short_chain_select;

    assign pin_based_scan = ctu_tst_scan_disable;
    assign se = global_shift_enable;
    assign testmode_l = ~ctu_tst_scanmode;
    assign mem_bypass = ~ctu_tst_macrotest & ~testmode_l;
    assign short_chain_en = ~(pin_based_scan & se);
    assign short_chain_select = ctu_tst_short_chain & ~testmode_l & short_chain_en;
    assign so_0 = short_chain_select ? short_chain_so_0 : long_chain_so_0;
    assign so_1 = short_chain_select ? short_chain_so_1 : long_chain_so_1;
    assign so_2 = short_chain_select ? short_chain_so_2 : long_chain_so_2;
    assign mux_drive_disable = ~ctu_tst_pre_grst_l | short_chain_select | se;
    assign mem_write_disable = ~ctu_tst_pre_grst_l | se;
    assign sehold = ctu_tst_macrotest & ~se;

endmodule

sva:
module scan_chain_interface_sva (
    input logic ctu_tst_pre_grst_l,
    input logic arst_l,
    input logic global_shift_enable,
    input logic ctu_tst_scan_disable,
    input logic ctu_tst_scanmode,
    input logic ctu_tst_macrotest,
    input logic ctu_tst_short_chain,
    input logic long_chain_so_0,
    input logic short_chain_so_0,
    input logic long_chain_so_1,
    input logic short_chain_so_1,
    input logic long_chain_so_2,
    input logic short_chain_so_2,
    input logic mux_drive_disable,
    input logic mem_write_disable,
    input logic sehold,
    input logic se,
    input logic testmode_l,
    input logic mem_bypass,
    input logic so_0,
    input logic so_1,
    input logic so_2
);

// No explicit clock in RTL; sample on posedge of global_shift_enable.
    // Active-low reset: ctu_tst_pre_grst_l (arst_l is unused).
    // Purely combinational logic; assertions check combinational definitions.

    ///// Direct signal definitions /////
    // se equals global_shift_enable.
    check_se_equals_gse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se == global_shift_enable
    );

// testmode_l is inverse of ctu_tst_scanmode.
    check_testmode_l_inverse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l == ~ctu_tst_scanmode
    );

// mem_bypass equals ~ctu_tst_macrotest & ~testmode_l.
    check_mem_bypass_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_bypass == (~ctu_tst_macrotest & ~testmode_l)
    );

// sehold equals ctu_tst_macrotest & ~se.
    check_sehold_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) sehold == (ctu_tst_macrotest & ~se)
    );

// mem_write_disable equals ~ctu_tst_pre_grst_l | se.
    check_mem_write_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable == (~ctu_tst_pre_grst_l | se)
    );

// mux_drive_disable equals ~ctu_tst_pre_grst_l | short_chain_select | se.
    check_mux_drive_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            mux_drive_disable == (~ctu_tst_pre_grst_l |
                                  (ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) |
                                  se)
    );

///// Scan-out mux selection /////
    // so_0 selects between short/long chain based on short_chain_select.
    check_so0_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_0 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_0 : long_chain_so_0)
    );

// so_1 selects between short/long chain based on short_chain_select.
    check_so1_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_1 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_1 : long_chain_so_1)
    );

// so_2 selects between short/long chain based on short_chain_select.
    check_so2_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_2 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_2 : long_chain_so_2)
    );

///// Derived implications (from direct definitions) /////
    // When testmode_l is HIGH, mem_bypass must be LOW.
    check_testmode_blocks_mem_bypass: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l |-> (mem_bypass == 1'b0)
    );

// When se is HIGH, sehold must be LOW.
    check_shift_disables_sehold: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se |-> (sehold == 1'b0)
    );

// mem_write_disable implies mux_drive_disable (mux_disable = memw_disable | short_chain_select).
    check_memw_implies_mux_disable: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable |-> mux_drive_disable
    );

endmodule

module shift_register_sva (
    input logic clk,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] out
);

// Clock: clk; no reset present in RTL.
    // Sequential behavior: on posedge clk, if load=1 load data; else shift left and insert data[3] at LSB.

    // Next-cycle out matches RTL next-state function based on prior cycle inputs.
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(load) ? $past(data) : {$past(out[2:0]), $past(data[3])}))
    );

// When load is 1, next-cycle out equals prior-cycle data.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (out == $past(data))
    );

// When load is 0, next-cycle out equals prior out shifted with prior data[3] into LSB.
    check_shift_concat: assert property (
        @(posedge clk) !load |=> (out == {$past(out[2:0]), $past(data[3])})
    );

// In shift mode, upper bits move from lower bits of prior out.
    check_shift_upper_bits_move: assert property (
        @(posedge clk) !load |=> (out[3:1] == $past(out[2:0]))
    );

// In shift mode, LSB becomes prior-cycle data[3].
    check_shift_lsb_source: assert property (
        @(posedge clk) !load |=> (out[0] == $past(data[3]))
    );

endmodule

rtl:
module kb_code
  (
    input wire clk, reset,scan_done_tick,
    input wire [7:0] scan_out,
    output reg got_code_tick
   );

   localparam BRK = 8'hf0; localparam
      wait_brk = 1'b0,
      get_code = 1'b1;

   reg state_reg, state_next;

   always @(posedge clk, posedge reset)
      if (reset)
         state_reg <= wait_brk;
      else
         state_reg <= state_next;

   always @*
   begin
      got_code_tick = 1'b0;
      state_next = state_reg;
      case (state_reg)
         wait_brk:  if (scan_done_tick==1'b1 && scan_out==BRK)
               state_next = get_code;
         get_code:  if (scan_done_tick)
               begin
                  got_code_tick =1'b1;
                  state_next = wait_brk;
               end
      endcase
   end

endmodule

sva:
module kb_code_sva (
    input logic clk,
    input logic reset,
    input logic scan_done_tick,
    input logic [7:0] scan_out,
    input logic got_code_tick
);

// While reset is asserted, output tick must be LOW.
    reset_clears_tick: assert property (
        @(posedge clk) reset |-> (got_code_tick == 1'b0)
    );

// No tick when scan_done_tick is LOW.
    tick_requires_done: assert property (
        @(posedge clk) disable iff (reset) (scan_done_tick == 1'b0) |-> (got_code_tick == 1'b0)
    );

// got_code_tick is a single-cycle pulse.
    tick_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> !got_code_tick
    );

// After a tick, remain LOW until a BRK code is observed with scan_done_tick.
    holdoff_until_break_after_tick: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> (!got_code_tick until (scan_done_tick && (scan_out == BRK)))
    );

// With back-to-back done pulses, if prior was not BRK in wait_brk, then no tick now.
    consecutive_done_without_break_no_tick: assert property (
        @(posedge clk) disable iff (reset)
