    check_y_equals_or_and: assert property (
        @(posedge CLK) Y == (B1 || (A1 && A2))
    );

// B1 HIGH forces Y HIGH.
    check_b1_implies_y_high: assert property (
        @(posedge CLK) B1 |-> Y
    );

// A1&A2 HIGH forces Y HIGH.
    check_a1a2_implies_y_high: assert property (
        @(posedge CLK) (A1 && A2) |-> Y
    );

