sva:
module sky130_fd_sc_ls__nand4b_sva (
    input logic CLK,
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C,
    input logic D
);

// Functional equivalence to NAND4 with inverted A_N.
    check_func_nand4b: assert property (
        @(posedge CLK) Y == ~(D & C & B & ~A_N)
    );

// Equivalent OR-of-literals form.
    check_func_or_form: assert property (
        @(posedge CLK) Y == (A_N | ~B | ~C | ~D)
    );

// A_N high forces Y high.
    check_an_high_forces_y_high: assert property (
        @(posedge CLK) A_N |-> (Y == 1'b1)
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

// C low forces Y high.
    check_c_low_forces_y_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// D low forces Y high.
    check_d_low_forces_y_high: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

// Y low only when A_N low and B,C,D high.
    check_y_low_only_when_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A_N == 1'b0 && B == 1'b1 && C == 1'b1 && D == 1'b1)
    );

// Rising A_N forces Y high.
    check_an_rise_forces_y_high: assert property (
        @(posedge CLK) $rose(A_N) |-> (Y == 1'b1)
    );

// Falling B forces Y high.
    check_b_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(B) |-> (Y == 1'b1)
    );

// Falling C forces Y high.
    check_c_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(C) |-> (Y == 1'b1)
    );

// Falling D forces Y high.
    check_d_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(D) |-> (Y == 1'b1)
    );

// Falling A_N with B,C,D high forces Y low.
    check_an_fall_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($fell(A_N) && B && C && D) |-> (Y == 1'b0)
    );

// Rising B with A_N low and C,D high forces Y low.
    check_b_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(B) && (A_N == 1'b0) && C && D) |-> (Y == 1'b0)
    );

// Rising C with A_N low and B,D high forces Y low.
    check_c_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(C) && (A_N == 1'b0) && B && D) |-> (Y == 1'b0)
    );

// Rising D with A_N low and B,C high forces Y low.
    check_d_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(D) && (A_N == 1'b0) && B && C) |-> (Y == 1'b0)
    );

endmodule

rtl:
module compare_module(
  input [1:0] A,
  input B,
  output Z
);

  assign Z = (A >= B) ? 1 : 0;

endmodule

sva:
module compare_module_sva (
    input logic [1:0] A,
    input logic       B,
    input logic       Z
);

// No clock or reset in DUT; combinational logic only. Sample on posedges of inputs.

    // Z equals (A >= B) when sampled on B's rising edge.
    check_func_eq_on_B: assert property (
        @(posedge B) Z == (A >= B)
    );

// Z equals (A >= B) when sampled on A[0]'s rising edge.
    check_func_eq_on_A0: assert property (
        @(posedge A[0]) Z == (A >= B)
    );

// Z equals (A >= B) when sampled on A[1]'s rising edge.
    check_func_eq_on_A1: assert property (
        @(posedge A[1]) Z == (A >= B)
    );

// If B is 0, Z must be 1 (A is unsigned and >= 0).
    check_b0_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b0) |-> (Z == 1'b1)
    );

// If B is 1 and A is 0, Z must be 0 (0 >= 1 is false).
    check_b1_a0_implies_z0: assert property (
        @(posedge A[1]) (B == 1'b1 && A == 2'b00) |-> (Z == 1'b0)
    );

// If B is 1 and A != 0, Z must be 1 (A in {1,2,3} >= 1).
    check_b1_a_nonzero_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b1 && A != 2'b00) |-> (Z == 1'b1)
    );

endmodule

module Incrementer_sva (
    input logic clk,                // external verification clock (RTL has no clock/reset)
    input logic [7:0] inValue,
    input logic [7:0] outValue
);

// When input is 0xFF, output wraps to 0x00.
    check_wrap_when_max: assert property (
        @(posedge clk) (inValue == 8'hFF) |-> (outValue == 8'h00)
    );

// When input is not 0xFF, output equals input + 1.
    check_increment_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue == inValue + 8'd1)
    );

// Only max input (0xFF) can produce output 0x00.
    check_zero_only_from_max: assert property (
        @(posedge clk) (outValue == 8'h00) |-> (inValue == 8'hFF)
    );

// Output 0xFF occurs only when input is 0xFE.
    check_out_ff_implies_in_fe: assert property (
        @(posedge clk) (outValue == 8'hFF) |-> (inValue == 8'hFE)
    );

// Output is never equal to input (no fixed point for +1 mod 256).
    check_out_never_equals_in: assert property (
        @(posedge clk) (outValue != inValue)
    );

// Output minus input is always 1 mod 256.
    check_modulo_difference_one: assert property (
        @(posedge clk) ((outValue - inValue) == 8'h01)
    );

// For non-max input, output is strictly greater than input.
    check_monotonic_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue > inValue)
    );

endmodule

rtl:
module synchronous_counter
(
    input clk,
    input reset,
    output reg [3:0] count
);

always @(posedge clk, posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else if (count == 4'b1001) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva:
module synchronous_counter_sva (
    input logic clk,
    input logic reset,          // active-HIGH asynchronous reset
    input logic [3:0] count
);

///// Reset behavior /////
    // While reset is asserted at the clock edge, count must be zero.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

///// Counting behavior (clocked) /////
    // If previous cycle was not in reset and count was within 0..9, it remains within 0..9.
    range_closed_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) <= 4'd9)) |-> (count <= 4'd9)
    );

// No two consecutive 9s when not in reset across the boundary.
    no_back_to_back_nine: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset)) |-> !($past(count) == 4'd9 && count == 4'd9)
    );

// From a previous value 9 without reset, next is 0 (wrap) or 1 (if async reset occurred mid-cycle).
    prev_nine_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) == 4'd9)) |-> ((count == 4'd0) || (count == 4'd1))
    );

// If the count decreases across cycles without reset, it can only drop to 0 or 1.
    decrease_only_to_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (count < $past(count))) |-> ((count == 4'd0) || (count == 4'd1))
    );

// When count is 9 (not in reset), the next cycle must be 0 or 1.
    next_after_nine_is_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'd9) |-> ##1 (count == 4'd0 || count == 4'd1)
    );

endmodule

module decoder_4to16_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [15:0] Y
);

// Output equals one-hot value of 1 shifted by A.
    check_decode_equivalence: assert property (
        @(posedge clk) Y == (16'h0001 << A)
    );

// Exactly one output bit is HIGH.
    check_onehot_output: assert property (
        @(posedge clk) $onehot(Y)
    );

// Output is never all zero for 4-bit binary A.
    check_nonzero_output: assert property (
        @(posedge clk) Y != 16'h0000
    );

// When MSB of A is 0, upper half of Y must be zero.
    check_upper_zero_when_msb0: assert property (
        @(posedge clk) (A[3] == 1'b0) |-> (Y[15:8] == 8'h00)
    );

// When MSB of A is 1, lower half of Y must be zero.
    check_lower_zero_when_msb1: assert property (
        @(posedge clk) (A[3] == 1'b1) |-> (Y[7:0] == 8'h00)
    );

// When A[3:2]==00, only Y[3:0] may be nonzero.
    check_quarter00_zero_upper12: assert property (
        @(posedge clk) (A[3:2] == 2'b00) |-> (Y[15:4] == 12'h000)
    );

// When A[3:2]==01, only Y[7:4] may be nonzero.
    check_quarter01_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b01) |-> (Y[15:8] == 8'h00 && Y[3:0] == 4'h0)
    );

// When A[3:2]==10, only Y[11:8] may be nonzero.
    check_quarter10_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b10) |-> (Y[15:12] == 4'h0 && Y[7:0] == 8'h00)
    );

// When A[3:2]==11, only Y[15:12] may be nonzero.
    check_quarter11_zero_lower12: assert property (
        @(posedge clk) (A[3:2] == 2'b11) |-> (Y[11:0] == 12'h000)
    );

// Corner case: A==0 decodes to Y==0x0001.
    check_decode_A0: assert property (
        @(posedge clk) (A == 4'd0) |-> (Y == 16'h0001)
    );

endmodule

rtl:
module sky130_fd_sc_hd__or2b (
    input A,
    input B_N,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output X
);

    reg A_reg;
    reg B_N_reg;
    reg X_reg;

    wire A_stable;
    wire B_N_stable;
    wire X_stable;

    assign A_stable = (A_reg === A);
    assign B_N_stable = (B_N_reg === B_N);
    assign X_stable = (X_reg === X);

    always @(posedge VPWR) begin // Using posedge operator for VPWR
        A_reg <= A;
        B_N_reg <= B_N;
    end

    always @(A or B_N or A_stable or B_N_stable or X_stable) begin
        if (A_stable && B_N_stable) begin
            X_reg <= A | B_N;
        end else begin
            X_reg <= #2 A | B_N;
        end
    end

    assign X = X_reg;

endmodule

sva:
module sky130_fd_sc_hd__or2b_sva (
    input logic A,
    input logic B_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

// Output is never Z at any VPWR rising edge.
    check_output_never_z: assert property (
        @(posedge VPWR) X !== 1'bz
    );

// When A and B_N are unchanged since last VPWR edge, X equals A | B_N.
    check_or_when_inputs_stable: assert property (
        @(posedge VPWR) (($past(A) === A) && ($past(B_N) === B_N)) |-> (X === (A | B_N))
    );

// Stable 0/0 inputs across a VPWR cycle yield X=0.
    check_tt_00: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b0)
    );

// Stable 0/1 inputs across a VPWR cycle yield X=1.
    check_tt_01: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

// Stable 1/0 inputs across a VPWR cycle yield X=1.
    check_tt_10: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b1)
    );

// Stable 1/1 inputs across a VPWR cycle yield X=1.
    check_tt_11: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

// With known inputs unchanged for two VPWR cycles, X is known (not X/Z).
    check_known_output_after_two_stable_cycles: assert property (
        @(posedge VPWR)
            ((A === 1'b0 || A === 1'b1) && (B_N === 1'b0 || B_N === 1'b1) &&
             ($past(A,2) === A) && ($past(B_N,2) === B_N))
            |-> ((X !== 1'bx) && (X !== 1'bz))
    );

// Changes on VPB/VGND/VNB do not affect X when A and B_N are stable across a VPWR cycle.
    check_supplies_no_effect_when_inputs_stable: assert property (
        @(posedge VPWR)
            (($past(A) === A) && ($past(B_N) === B_N) &&
             (($past(VPB) !== VPB) || ($past(VGND) !== VGND) || ($past(VNB) !== VNB)))
            |-> (X === (A | B_N))
    );

endmodule

rtl:
module fa1 (
    A, 
    B, 
    CI, 
    S, 
    CO);
   input A;
   input B;
   input CI;
   output S;
   output CO;
   assign S = A ^ B ^ CI;
   assign CO = (A & B) | (CI & (A ^ B));
endmodule

module addsub4 (
    A, 
    B, 
    M, 
    Y);
   input [3:0] A;
   input [3:0] B;
   input M;
   output [3:0] Y;
   wire [3:0] C;
   wire [3:0] S;
   fa1 fa1_0(A[0], B[0], M, S[0], C[0]);
   fa1 fa1_1(A[1], B[1], C[0], S[1], C[1]);
   fa1 fa1_2(A[2], B[2], C[1], S[2], C[2]);
   fa1 fa1_3(A[3], B[3], C[2], S[3], C[3]);
   assign Y = M ? A - B : A + B;
endmodule

sva:
module addsub4_sva (
    // No clock/reset in RTL; pure combinational. Sampling clock provided here.
    input logic CLK,
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       M,
    input logic [3:0] Y,
    // Internal nets from RTL (fa1 chain)
    input logic [3:0] C,
    input logic [3:0] S
);

// C[1] equals (A[1]&B[1]) | (C[0] & (A[1]^B[1])).
    fa1_carry_def: assert property (
        @(posedge CLK) C[1] == ((A[1] & B[1]) | (C[0] & (A[1] ^ B[1])))
    );

///// fa1_2 (bit 2) behavior /////
    // S[2] equals A[2] ^ B[2] ^ C[1].
    fa2_sum_def: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ C[1])
    );

// C[2] equals (A[2]&B[2]) | (C[1] & (A[2]^B[2])).
    fa2_carry_def: assert property (
        @(posedge CLK) C[2] == ((A[2] & B[2]) | (C[1] & (A[2] ^ B[2])))
    );

///// fa1_3 (bit 3) behavior /////
    // S[3] equals A[3] ^ B[3] ^ C[2].
    fa3_sum_def: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ C[2])
    );

// C[3] equals (A[3]&B[3]) | (C[2] & (A[3]^B[3])).
    fa3_carry_def: assert property (
        @(posedge CLK) C[3] == ((A[3] & B[3]) | (C[2] & (A[3] ^ B[3])))
    );

endmodule

