module xor_32_refactored(
	input [31:0] a, //input values
	input [31:0] b,
	output [31:0] out //output value
	);

	//output is the XOR of a and b
	assign out = a ^ b;

endmodule

sva:
module xor_32_refactored_sva (
    input  logic        clk,    // external sampling clock
    input  logic        rst_n,  // external active-low reset for disabling assertions
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [31:0] out
);

// Output equals bitwise XOR of a and b.
    check_xor_definition: assert property (
        @(posedge clk) disable iff (!rst_n) out == (a ^ b)
    );

// If a is zero, output passes through b.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (!rst_n) (a == 32'h0) |-> (out == b)
    );

// If b is zero, output passes through a.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (!rst_n) (b == 32'h0) |-> (out == a)
    );

// If inputs are equal, output is zero.
    check_equal_inputs_zero_out: assert property (
        @(posedge clk) disable iff (!rst_n) (a == b) |-> (out == 32'h0)
    );

// If output is zero, inputs are equal.
    check_zero_out_implies_equal_inputs: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 32'h0) |-> (a == b)
    );

// Self-inverse: (a ^ b) ^ b == a.
    check_self_inverse_via_b: assert property (
        @(posedge clk) disable iff (!rst_n) ((out ^ b) == a)
    );

// Self-inverse: (a ^ b) ^ a == b.
    check_self_inverse_via_a: assert property (
        @(posedge clk) disable iff (!rst_n) ((out ^ a) == b)
    );

endmodule

rtl:
module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input [1:0] S,
    output Y
);

wire w1, w2, w3;

assign w1 = (S == 2'b00) ? A : B;
assign w2 = (S == 2'b00 || S == 2'b01) ? w1 : C;
assign w3 = (S == 2'b00 || S == 2'b01 || S == 2'b10) ? w2 : D;
assign Y = w3;

endmodule

sva:
module mux4to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic [1:0] S,
    input logic Y
);

///// Functional mapping /////
    // Y equals the 4:1 mux function of S selecting A/B/C/D.
    check_mux_equation: assert property (
        @(posedge CLK) Y == ((S == 2'b00) ? A :
                             (S == 2'b01) ? B :
                             (S == 2'b10) ? C : D)
    );

// When S==00, Y must equal A.
    check_sel_00: assert property (
        @(posedge CLK) (S == 2'b00) |-> (Y == A)
    );

// When S==01, Y must equal B.
    check_sel_01: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Y == B)
    );

// When S==10, Y must equal C.
    check_sel_10: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Y == C)
    );

// When S==11, Y must equal D.
    check_sel_11: assert property (
        @(posedge CLK) (S == 2'b11) |-> (Y == D)
    );

endmodule

module counter_sva (
  input logic clk,
  input logic ce,
  input logic clr,
  input logic [7:0] count
);

// Synchronous clear drives count to zero on that clock.
  sync_clear_zero: assert property (
    @(posedge clk) clr |=> (count == 8'h00)
  );

// With enable and no clear (prev cycle not in clear), count increments by 1.
  inc_on_ce: assert property (
    @(posedge clk) disable iff (clr)
      (ce && $past(!clr)) |=> (count == $past(count) + 8'd1)
  );

// With ce low and no clear (prev cycle not in clear), count holds.
  hold_when_ce_low: assert property (
    @(posedge clk) disable iff (clr)
      (!ce && $past(!clr)) |=> (count == $past(count))
  );

// clr dominates ce when both are high.
  clr_priority_over_ce: assert property (
    @(posedge clk) (clr && ce) |=> (count == 8'h00)
  );

endmodule

rtl:
module RCA_N4_17 ( A, B, Ci, S, Co );
  input [3:0] A;
  input [3:0] B;
  output [3:0] S;
  input Ci;
  output Co;

  wire   [3:1] CTMP;

  FA_71 FAI_1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(CTMP[1]) );
  FA_70 FAI_2 ( .A(A[1]), .B(B[1]), .Ci(CTMP[1]), .S(S[1]), .Co(CTMP[2]) );
  FA_69 FAI_3 ( .A(A[2]), .B(B[2]), .Ci(CTMP[2]), .S(S[2]), .Co(CTMP[3]) );
  FA_68 FAI_4 ( .A(A[3]), .B(B[3]), .Ci(CTMP[3]), .S(S[3]), .Co(Co) );

endmodule

module FA_71 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_70 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_69 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
endmodule

module FA_68 ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  assign S = A ^ B ^ Ci;
  assign Co = (A & B) | (A & Ci) | (B & Ci);
