sva:
module RCA_N4_17_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Ci,
    input logic [3:0] S,
    input logic Co
);

// Sum and carry must equal 5-bit addition of A+B+Ci.
    check_sum_matches_adder: assert property (
        @(posedge CLK) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// Carry-out equals MSB of 5-bit sum.
    check_carry_is_msb_of_sum: assert property (
        @(posedge CLK) Co == (({1'b0, A} + {1'b0, B} + Ci) >= 5'd16)
    );

// Bit 0 sum is XOR of A[0], B[0], Ci.
    check_s0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit 1 sum is XOR of A[1], B[1], and c1.
    check_s1_xor: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
    );

// Bit 2 sum is XOR of A[2], B[2], and c2.
    check_s2_xor: assert property (
        @(posedge CLK) S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
            )
        )
    );

// Bit 3 sum is XOR of A[3], B[3], and c3.
    check_s3_xor: assert property (
        @(posedge CLK) S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (A[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                        (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                    )
                ) |
                (B[2] &
                    (
                        (A[1] & B[1]) |
                        (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                        (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                    )
                )
            )
        )
    );

// Carry-out equals chained majority over bit 3 with c3.
    check_co_chained_majority: assert property (
        @(posedge CLK) Co == (
            (A[3] & B[3]) |
            (A[3] &
                (
                    (A[2] & B[2]) |
                    (A[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    ) |
                    (B[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    )
                )
            ) |
            (B[3] &
                (
                    (A[2] & B[2]) |
                    (A[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    ) |
                    (B[2] &
                        (
                            (A[1] & B[1]) |
                            (A[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) )) |
                            (B[1] & ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
                        )
                    )
                )
            )
        )
    );

// When B==0 and Ci==0, output equals A with zero carry.
    check_propagate_A_when_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

// When A==0 and Ci==0, output equals B with zero carry.
    check_propagate_B_when_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

endmodule

rtl:
module bw_ioslave_dl(
	// inputs in alphabetical order
	dqs_in,
	lpf_out,
	se,
	si,
	strobe,
	//outputs in alphabetical order
	dqs_out,
	so          );

	input		dqs_in;
	input [4:0]	lpf_out;
	input		se;
	input		si;
	input		strobe;

	output		dqs_out;
	output		reg so;

       parameter DELAY = 1250;

        reg             dqs_out;
        reg             q1;
        reg             q2;
        reg             q3;
        reg             q4;

        // 1/4 cycle delay line.
        always @(posedge dqs_in)
          begin
            q1 <= #DELAY dqs_in;
            q2 <= #DELAY q1;
            q3 <= #DELAY q2;
            q4 <= #DELAY q3;
            dqs_out <= #DELAY q4;
          end

        // strobe output
        always @(posedge strobe)
          begin
            if (se == 1)
              so <= si;
          end

endmodule

sva:
module bw_ioslave_dl_sva (
    input logic dqs_in,
    input logic [4:0] lpf_out,
    input logic se,
    input logic si,
    input logic strobe,
    input logic dqs_out,
    input logic so
);

// Clocks: posedge dqs_in, posedge strobe; no reset in RTL.
    // Sequential logic: 5-stage delay line on dqs_in; so is registered on strobe when se=1.

    ///// dqs_in delay line behavior /////
    // dqs_out equals dqs_in delayed by 5 posedges of dqs_in.
    check_dqsout_delay_5: assert property (
        @(posedge dqs_in) 1'b1 |-> ##5 (dqs_out == $past(dqs_in,5))
    );

///// strobe/so register behavior /////
    // When se==1 at strobe edge, so captures si.
    check_so_captures_si_when_se: assert property (
        @(posedge strobe) se |=> (so == $past(si))
    );

// When se==0 at strobe edge, so holds its previous value.
    check_so_holds_when_se_low: assert property (
        @(posedge strobe) !se |=> (so == $past(so))
    );

endmodule

rtl:
module binary_adder (
    input [3:0] A,
    input [3:0] B,
    output reg [3:0] S
);

always @(*) begin
    S = A + B;
    if (S > 15) begin
        S = S - 16;
    end
end

endmodule

sva:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S
);

// S equals (A+B) modulo 16.
    check_sum_mod16: assert property (
        @(posedge clk) S == ((A + B) & 4'hF)
    );

// Adding zero on B leaves S equal to A.
    check_identity_B_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (S == A)
    );

// Adding zero on A leaves S equal to B.
    check_identity_A_zero: assert property (
        @(posedge clk) (A == 4'd0) |-> (S == B)
    );

// Both inputs zero results in zero sum.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 4'd0 && B == 4'd0) |-> (S == 4'd0)
    );

endmodule

rtl:
module nios_dut_pio_2 (
                        // inputs:
                         address,
                         clk,
                         in_port,
                         reset_n,

                        // outputs:
                         readdata
                      )
;

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [ 19: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [ 19: 0] data_in;
  wire    [ 19: 0] read_mux_out;
  reg     [ 31: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {20 {(address == 2'b00)}} & data_in | {12'b0, in_port[19:0]} & {20 {(address == 2'b01)}};
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end


  assign data_in = in_port;

endmodule

sva:
module nios_dut_pio_2_sva (
    input  logic        clk,
    input  logic        reset_n,   // active-low
    input  logic [1:0]  address,
    input  logic [19:0] in_port,
    input  logic [31:0] readdata
);

///// Reset behavior /////
    // During reset, readdata must be 0.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'h0)
    );

///// Output formatting /////
    // Upper 12 bits of readdata are always zero when not in reset.
    check_readdata_upper_zero: assert property (
        @(posedge clk) disable iff (!reset_n) readdata[31:20] == 12'b0
    );

// Next-cycle readdata is zero when previous address was 2'b10 or 2'b11.
    check_update_on_addr_other_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
            $past(reset_n) && ($past(address) inside {2'b10,2'b11}) |->
                (readdata == 32'h0)
    );

endmodule

rtl:
module mux_2to1(
    input A,
    input B,
    input S,
    output Y
);

    wire not_S;
    assign not_S = ~S;

    wire Y_A;
    wire Y_B;

    and gate_A(Y_A, A, not_S);
    and gate_B(Y_B, B, S);

    or gate_C(Y, Y_A, Y_B);

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

// Y implements 2:1 mux function: Y = (~S & A) | (S & B).
    check_mux_function: assert property (
        @(posedge CLK) Y == ((~S & A) | (S & B))
    );

// When S=0, Y equals A.
    check_select_low: assert property (
        @(posedge CLK) (S == 1'b0) |-> (Y == A)
    );

// When S=1, Y equals B.
    check_select_high: assert property (
        @(posedge CLK) (S == 1'b1) |-> (Y == B)
    );

// If A and B are equal, Y equals that value.
    check_equal_inputs: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

// On S rising edge, Y equals B in the same cycle.
