module half_adder_nand( 
    input a, b,
    output sum, cout );

    wire s1, s2, c1;

    nand(s1, a, b);
    nand(s2, a, s1);
    nand(c1, s1, b);

    assign sum = s2;
    assign cout = c1;

endmodule

sva:
module half_adder_nand_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sum,
    input logic cout
);

// Sum equals (~a | b).
    check_sum_function: assert property (
        @(posedge clk) disable iff (1'b0) sum == ((~a) | b)
    );

// Cout equals (a | ~b).
    check_cout_function: assert property (
        @(posedge clk) disable iff (1'b0) cout == (a | (~b))
    );

// At least one output is HIGH at all times.
    check_sum_or_cout_one: assert property (
        @(posedge clk) disable iff (1'b0) (sum | cout) == 1'b1
    );

// Output XOR equals input XOR.
    check_xor_relation: assert property (
        @(posedge clk) disable iff (1'b0) (sum ^ cout) == (a ^ b)
    );

// For a=0,b=0 -> sum=1, cout=1.
    check_tt_00: assert property (
        @(posedge clk) disable iff (1'b0) (!a && !b) |-> (sum && cout)
    );

// For a=0,b=1 -> sum=1, cout=0.
    check_tt_01: assert property (
        @(posedge clk) disable iff (1'b0) (!a && b) |-> (sum && !cout)
    );

// For a=1,b=0 -> sum=0, cout=1.
    check_tt_10: assert property (
        @(posedge clk) disable iff (1'b0) (a && !b) |-> (!sum && cout)
    );

// For a=1,b=1 -> sum=1, cout=1.
    check_tt_11: assert property (
        @(posedge clk) disable iff (1'b0) (a && b) |-> (sum && cout)
    );

// Sum is LOW only when a=1 and b=0.
    check_sum_zero_only_on_10: assert property (
        @(posedge clk) disable iff (1'b0) (sum == 1'b0) |-> (a && !b)
    );

// Cout is LOW only when a=0 and b=1.
    check_cout_zero_only_on_01: assert property (
        @(posedge clk) disable iff (1'b0) (cout == 1'b0) |-> (!a && b)
    );

endmodule

rtl:
module synchronous_counter(CLK, RST, LOAD, EN, DATA_IN, DATA_OUT);

input CLK, RST, LOAD, EN;
input [3:0] DATA_IN;
output reg [3:0] DATA_OUT;

always @(posedge CLK) begin
    if (RST) begin
        DATA_OUT <= 4'b0;
    end else if (LOAD) begin
        DATA_OUT <= DATA_IN;
    end else if (EN) begin
        if (DATA_OUT == 4'b1111) begin
            DATA_OUT <= 4'b0;
        end else begin
            DATA_OUT <= DATA_OUT + 1;
        end
    end
end

endmodule

sva:
module synchronous_counter_sva (
    input logic CLK,
    input logic RST,
    input logic LOAD,
    input logic EN,
    input logic [3:0] DATA_IN,
    input logic [3:0] DATA_OUT
);

// Clock: CLK (posedge). Reset: RST active-high, synchronous. Logic: sequential.
    // Behavior: RST->0; LOAD->DATA_OUT:=DATA_IN; else if EN->count with wrap; else hold.

    // On RST high at a clock, DATA_OUT becomes 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (DATA_OUT == 4'b0000)
    );

// LOAD updates DATA_OUT with DATA_IN on the next cycle.
    load_captures_data_in: assert property (
        @(posedge CLK) disable iff (RST) LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

// LOAD has priority over EN when both are asserted.
    load_overrides_en: assert property (
        @(posedge CLK) disable iff (RST) (LOAD && EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// With EN and not LOAD, non-max value increments by 1 on the next cycle.
    en_increments_nonmax: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT != 4'hF)) |=> (DATA_OUT == $past(DATA_OUT) + 4'd1)
    );

// With EN and not LOAD, 4'hF wraps to 0 on the next cycle.
    en_wraps_at_max_to_zero: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT == 4'hF)) |=> (DATA_OUT == 4'h0)
    );

// With neither EN nor LOAD, DATA_OUT holds its previous value.
    holds_when_idle: assert property (
        @(posedge CLK) disable iff (RST) (!EN && !LOAD) |=> (DATA_OUT == $past(DATA_OUT))
    );

// With EN and not LOAD, DATA_OUT must change (either increment or wrap).
    en_causes_change: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD) |=> (DATA_OUT != $past(DATA_OUT))
    );

// When not RESET and not LOAD, the only allowed transitions are hold, +1, or wrap.
    allowed_transitions_without_load: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !LOAD) |=> (
                // hold when EN==0
                (( !$past(EN) ) && (DATA_OUT == $past(DATA_OUT))) ||
                // +1 when EN==1 and not max
                (( $past(EN) && ($past(DATA_OUT) != 4'hF) ) && (DATA_OUT == $past(DATA_OUT) + 4'd1)) ||
                // wrap to 0 when EN==1 and max
                (( $past(EN) && ($past(DATA_OUT) == 4'hF) ) && (DATA_OUT == 4'h0))
            )
    );

endmodule

rtl:
module and_gate (
    input A,
    input B,
    input C,
    output Y
);

    assign Y = A & B & C;

endmodule

sva:
module and_gate_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);

// No clock/reset in RTL; pure combinational AND. Assertions sample on input posedges.

    // Y must equal A & B & C sampled on posedge A.
    check_y_matches_and_on_A: assert property (
        @(posedge A) Y == (A & B & C)
    );

// Y must equal A & B & C sampled on posedge B.
    check_y_matches_and_on_B: assert property (
        @(posedge B) Y == (A & B & C)
    );

// Y must equal A & B & C sampled on posedge C.
    check_y_matches_and_on_C: assert property (
        @(posedge C) Y == (A & B & C)
    );

// When B and C are HIGH, Y follows A on posedge A.
    check_follow_A_when_BC_high: assert property (
        @(posedge A) (B && C) |-> (Y == A)
    );

// When A and C are HIGH, Y follows B on posedge B.
    check_follow_B_when_AC_high: assert property (
        @(posedge B) (A && C) |-> (Y == B)
    );

// When A and B are HIGH, Y follows C on posedge C.
    check_follow_C_when_AB_high: assert property (
        @(posedge C) (A && B) |-> (Y == C)
    );

// If B is LOW, Y must be LOW on posedge A.
    check_y_zero_when_B_zero_on_A: assert property (
        @(posedge A) (!B) |-> (Y == 1'b0)
    );

// If C is LOW, Y must be LOW on posedge A.
    check_y_zero_when_C_zero_on_A: assert property (
        @(posedge A) (!C) |-> (Y == 1'b0)
    );

// If Y is HIGH on posedge B, A and C must be HIGH.
    check_y_high_implies_A_and_C_high_on_B: assert property (
        @(posedge B) Y |-> (A && C)
    );

// If Y is HIGH on posedge C, A and B must be HIGH.
    check_y_high_implies_A_and_B_high_on_C: assert property (
        @(posedge C) Y |-> (A && B)
    );

endmodule

rtl:
module mux_3to4_enable (
  input clk,
  input reset,
  input enable,
  input [2:0] A,
  input [2:0] B,
  input [2:0] C,
  output reg [2:0] W,
  output reg [2:0] X,
  output reg [2:0] Y,
  output reg [2:0] Z
);

  always @(posedge clk) begin
    if (reset) begin
      W <= 3'b0;
      X <= 3'b0;
      Y <= 3'b0;
      Z <= 3'b0;
    end else begin
      if (enable) begin
        W <= A;
        X <= B;
        Y <= B;
        Z <= 3'b0;
      end else begin
        W <= 3'b0;
        X <= 3'b0;
        Y <= 3'b0;
        Z <= C;
      end
    end
  end

endmodule

sva:
module mux_3to4_enable_sva (
  input logic clk,
  input logic reset,
  input logic enable,
  input logic [2:0] A,
  input logic [2:0] B,
  input logic [2:0] C,
  input logic [2:0] W,
  input logic [2:0] X,
  input logic [2:0] Y,
  input logic [2:0] Z
);

// Clock: clk; Reset: reset (active-high, synchronous)
  // Logic: sequential; outputs registered on posedge clk
  // Function: if enable then W=A, X=Y=B, Z=0; else W=X=Y=0, Z=C (visible next cycle)

  // Synchronous reset drives all outputs to zero on the next cycle.
  reset_clears_outputs_next: assert property (
    @(posedge clk) reset |=> (W == 3'b000) && (X == 3'b000) && (Y == 3'b000) && (Z == 3'b000)
  );

// W next-cycle equals A when enable is 1, else 0.
  w_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (W == ($past(enable) ? $past(A) : 3'b000))
  );

// X next-cycle equals B when enable is 1, else 0.
  x_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == ($past(enable) ? $past(B) : 3'b000))
  );

// Y next-cycle equals B when enable is 1, else 0.
  y_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Y == ($past(enable) ? $past(B) : 3'b000))
  );

// Z next-cycle equals 0 when enable is 1, else C.
  z_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Z == ($past(enable) ? 3'b000 : $past(C)))
  );

// X and Y are always equal from the next cycle onward.
  x_equals_y_next_cycle: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == Y)
  );

endmodule

rtl:
module top_module (
    input clk,
    input slowena,
    input reset,
    input select,
    input a,
    input b,
    output reg out
);

reg [3:0] count;
wire xor_out;

// Decade counter
always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else if (slowena) begin
        count <= count;
    end else begin
        count <= count + 1;
    end
end

// XOR gate
assign xor_out = a ^ b;

// Control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        out <= 1'b0;
    end else begin
        if (select) begin
            out <= xor_out;
        end else begin
            out <= count[3];
        end
    end
end

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic slowena,
    input logic reset,
    input logic select,
    input logic a,
    input logic b,
    input logic out,
    input logic [3:0] count,
    input logic xor_out
);

// Clock: clk. Reset: reset (active-high async in RTL). Mixed sequential/combinational logic.

    ///// Reset behavior /////
    // During reset, counter is 0.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// During reset, out is 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 1'b0)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic LOAD,
    input logic RESET,      // Active-high synchronous reset
    input logic [1:0] DATA,
    input logic [1:0] Q
);

// Clock: clk (posedge). Reset: RESET (active-high, synchronous).
    // Behavior: if RESET then Q<=0; else if LOAD then Q<=DATA; else Q<=Q+1 (2-bit wrap).

    // Synchronous reset drives Q to 0 on the next clock.
    reset_clears_q: assert property (
        @(posedge clk) RESET |=> (Q == 2'b00)
    );

// Next-state matches RTL when not in reset: load has priority else increment.
    next_state_matches_rtl: assert property (
        @(posedge clk) disable iff (RESET)
            1'b1 |=> (Q == ($past(LOAD) ? $past(DATA) : ($past(Q) + 2'b01)))
    );

// When LOAD is asserted (no reset), Q updates to DATA on the next clock.
    next_q_on_load: assert property (
        @(posedge clk) disable iff (RESET)
            LOAD |=> (Q == $past(DATA))
    );

// When LOAD is deasserted (no reset), Q increments by 1 on the next clock.
    next_q_on_no_load_increment: assert property (
        @(posedge clk) disable iff (RESET)
            !LOAD |=> (Q == ($past(Q) + 2'b01))
    );

// Increment wraps from 3 to 0 when LOAD is low (no reset).
    increment_wraps_at_3: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD && (Q == 2'b11)) |=> (Q == 2'b00)
    );

// With LOAD low for two cycles (no reset), Q increases by 2 over two clocks.
    two_cycle_increment_when_no_load: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD ##1 !LOAD) |=> (Q == ($past(Q,2) + 2'd2))
    );

// With LOAD high for two cycles (no reset), Q follows DATA from the immediately preceding cycle.
    two_consecutive_loads_follow_data: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 LOAD) |=> (Q == $past(DATA,1))
    );

// LOAD followed by no-LOAD (no reset): Q becomes loaded DATA then increments next.
    load_then_increment: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 !LOAD) |=> (Q == ($past(DATA,2) + 2'b01))
    );

endmodule

