rtl:
module Multiplexer #(parameter INIT_VALUE = 8'hB8)
   (input ctrl,
    input [0:0] D0,
    input [0:0] D1,
    output reg [0:0] S);

  wire [0:0] D0_wire;
  wire [0:0] D1_wire;
