sva:
module Multiplexer_sva (
    input logic CLK,          // External sampling clock for assertions
    input logic ctrl,
    input logic [0:0] D0,
    input logic [0:0] D1,
    input logic [0:0] S
);

// When ctrl is 0, S equals D0.
    check_select0: assert property (
        @(posedge CLK) (ctrl === 1'b0) |-> (S === D0)
    );

// When ctrl is 1, S equals D1.
    check_select1: assert property (
        @(posedge CLK) (ctrl === 1'b1) |-> (S === D1)
    );

// On ctrl rising edge, output selects D1.
    check_ctrl_rise_selects_D1: assert property (
        @(posedge CLK) $rose(ctrl) |-> (S === D1)
    );

// On ctrl falling edge, output selects D0.
    check_ctrl_fall_selects_D0: assert property (
        @(posedge CLK) $fell(ctrl) |-> (S === D0)
    );

// When ctrl=0 and D0 changes, S immediately reflects D0.
    check_selected_input_update_sel0: assert property (
        @(posedge CLK) (ctrl === 1'b0) && $stable(ctrl) && $changed(D0) |-> (S === D0)
    );

// When ctrl=1 and D1 changes, S immediately reflects D1.
    check_selected_input_update_sel1: assert property (
        @(posedge CLK) (ctrl === 1'b1) && $stable(ctrl) && $changed(D1) |-> (S === D1)
    );

// With ctrl=0 and differing inputs, S is not equal to D1.
    check_exclusive_if_inputs_differ_sel0: assert property (
        @(posedge CLK) (ctrl === 1'b0) && (D0 !== D1) |-> (S !== D1)
    );

// With ctrl=1 and differing inputs, S is not equal to D0.
    check_exclusive_if_inputs_differ_sel1: assert property (
        @(posedge CLK) (ctrl === 1'b1) && (D0 !== D1) |-> (S !== D0)
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,      // active-low asynchronous reset
    input logic en,
    input logic [3:0] count
);

// Reset low forces count to 0 at each clock.
    check_count_reset_value: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// If the previous cycle was in reset, count is 0 now.
    check_count_zero_after_prev_reset: assert property (
        @(posedge clk) $past(!rst, 1, 1'b0) |-> (count == 4'd0)
    );

// With reset high, current count can only be previous, previous+1, or 0.
    check_allowed_transitions_when_rst_high: assert property (
        @(posedge clk) disable iff (!rst)
            $past(1'b1) |-> ( (count == $past(count)) || (count == ($past(count) + 4'd1)) || (count == 4'd0) )
    );

// With en=0 and reset high, next count either holds or goes to 0 (if reset asserted between).
    check_next_when_en0_hold_or_reset: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && !en) |=> ( (count == $past(count)) || (count == 4'd0) )
    );

// With en=1 and reset high, next count is previous+1 or 0 (if reset asserted between).
    check_next_when_en1_inc_or_reset: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && en) |=> ( (count == ($past(count) + 4'd1)) || (count == 4'd0) )
    );

// With reset high, count never decreases except to 0 (wrap or reset).
    check_no_decrement_except_zero: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && (count < $past(count))) |-> (count == 4'd0)
    );

endmodule

rtl:
module verilog_module (
    input in1,
    input in2,
    input in3,
    input in4,
    input in5,
    input in6,
    input in7,
    input in8,
    output out1,
    output out2,
    output out3,
    output out4
);

    assign out1 = in1 & in2 & in3;
    assign out2 = in4 | in5 | in6;
    assign out3 = in7 ^ in8;
    assign out4 = ~in1;

endmodule

sva:
module verilog_module_sva (
    input logic CLK,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic in5,
    input logic in6,
    input logic in7,
    input logic in8,
    input logic out1,
    input logic out2,
    input logic out3,
    input logic out4
);

///// out1 = in1 & in2 & in3 /////
    // out1 equals bitwise AND of in1,in2,in3.
    check_out1_is_and: assert property (
        @(posedge CLK) out1 === (in1 & in2 & in3)
    );

// If out1 is 1 then all in1,in2,in3 are 1.
    check_out1_high_inputs_all_high: assert property (
        @(posedge CLK) (out1 == 1'b1) |-> ((in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1))
    );

// If in1 is 0 then out1 is 0.
    check_in1_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in1 == 1'b0) |-> (out1 == 1'b0)
    );

// If in2 is 0 then out1 is 0.
    check_in2_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in2 == 1'b0) |-> (out1 == 1'b0)
    );

// If in3 is 0 then out1 is 0.
    check_in3_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in3 == 1'b0) |-> (out1 == 1'b0)
    );

///// out2 = in4 | in5 | in6 /////
    // out2 equals bitwise OR of in4,in5,in6.
    check_out2_is_or: assert property (
        @(posedge CLK) out2 === (in4 | in5 | in6)
    );

// If out2 is 0 then all in4,in5,in6 are 0.
    check_out2_low_inputs_all_low: assert property (
        @(posedge CLK) (out2 == 1'b0) |-> ((in4 == 1'b0) && (in5 == 1'b0) && (in6 == 1'b0))
    );

// If in4 is 1 then out2 is 1.
    check_in4_one_forces_out2_one: assert property (
        @(posedge CLK) (in4 == 1'b1) |-> (out2 == 1'b1)
    );

// If in5 is 1 then out2 is 1.
    check_in5_one_forces_out2_one: assert property (
        @(posedge CLK) (in5 == 1'b1) |-> (out2 == 1'b1)
    );

// If in6 is 1 then out2 is 1.
    check_in6_one_forces_out2_one: assert property (
        @(posedge CLK) (in6 == 1'b1) |-> (out2 == 1'b1)
    );

///// out3 = in7 ^ in8 /////
    // out3 equals bitwise XOR of in7,in8.
    check_out3_is_xor: assert property (
        @(posedge CLK) out3 === (in7 ^ in8)
    );

// If in7=0 and in8=0 then out3=0.
    check_xor_00_is_0: assert property (
        @(posedge CLK) ((in7 == 1'b0) && (in8 == 1'b0)) |-> (out3 == 1'b0)
    );

// If in7=1 and in8=1 then out3=0.
    check_xor_11_is_0: assert property (
        @(posedge CLK) ((in7 == 1'b1) && (in8 == 1'b1)) |-> (out3 == 1'b0)
    );

// If in7=1 and in8=0 then out3=1.
    check_xor_10_is_1: assert property (
        @(posedge CLK) ((in7 == 1'b1) && (in8 == 1'b0)) |-> (out3 == 1'b1)
    );

// If in7=0 and in8=1 then out3=1.
    check_xor_01_is_1: assert property (
        @(posedge CLK) ((in7 == 1'b0) && (in8 == 1'b1)) |-> (out3 == 1'b1)
    );

///// out4 = ~in1 /////
    // out4 equals bitwise NOT of in1.
    check_out4_is_not: assert property (
        @(posedge CLK) out4 === (~in1)
    );

// If in1 is 1 then out4 is 0.
    check_not_in1_1_out4_0: assert property (
        @(posedge CLK) (in1 == 1'b1) |-> (out4 == 1'b0)
    );

// If in1 is 0 then out4 is 1.
    check_not_in1_0_out4_1: assert property (
        @(posedge CLK) (in1 == 1'b0) |-> (out4 == 1'b1)
    );

endmodule

rtl:
module mux(input ctrl, input [0:0] D0, input [0:0] D1, output [0:0] S);
  wire [0:0] D0_wire;
  wire [0:0] D1_wire;
  wire [0:0] S_wire;
  wire ctrl_wire;

  assign D0_wire[0] = D0[0];
  assign D1_wire[0] = D1[0];

  assign S[0] = S_wire[0];

  assign ctrl_wire = ctrl;

  assign S_wire[0] = (ctrl_wire) ? D1_wire[0] : D0_wire[0];
