rtl:
module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    input [3:0] D,
    output EQ,
    output GT
);

wire eq1, eq2, eq3, gt1, gt2, gt3, gt4, gt5;

// Check if A=B
assign eq1 = (A == B);

// Check if B=C
assign eq2 = (B == C);

// Check if C=D
assign eq3 = (C == D);

// Check if A>B
assign gt1 = (A > B);

// Check if B>C
assign gt2 = (B > C);

// Check if C>D
assign gt3 = (C > D);

// Check if A>B>C>D
assign gt4 = (gt1 && gt2 && gt3);

// Check if A=B=C=D
assign gt5 = (eq1 && eq2 && eq3);

// Output EQ
assign EQ = (eq1 && eq2 && eq3);

// Output GT
assign GT = (gt4 || gt5);

endmodule

sva:
module comparator_4bit_sva(
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic EQ,
    input logic GT
);

// No reset is present in the RTL; sample combinational behavior on clk.

    // EQ is high exactly when all four inputs are equal.
    check_eq_definition: assert property (
        @(posedge clk) EQ === ((A == B) && (B == C) && (C == D))
    );

// GT is high exactly for strict descending order or the all-equal case.
    check_gt_definition: assert property (
        @(posedge clk) GT === (((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D)))
    );

// All equal inputs drive both EQ and GT high.
    check_all_equal_outputs_high: assert property (
        @(posedge clk) ((A == B) && (B == C) && (C == D)) |-> ((EQ === 1'b1) && (GT === 1'b1))
    );

// Strict descending inputs drive GT high and EQ low.
    check_strict_descending_outputs: assert property (
        @(posedge clk) ((A > B) && (B > C) && (C > D)) |-> ((GT === 1'b1) && (EQ === 1'b0))
    );

// EQ can only be high when GT is also high.
    check_eq_implies_gt: assert property (
        @(posedge clk) (EQ === 1'b1) |-> (GT === 1'b1)
    );

// GT without EQ means the inputs are strictly descending.
    check_gt_without_eq_means_descending: assert property (
        @(posedge clk) ((GT === 1'b1) && (EQ === 1'b0)) |-> ((A > B) && (B > C) && (C > D))
    );

// Any break in the equality chain keeps EQ low.
    check_mismatch_clears_eq: assert property (
        @(posedge clk) !((A == B) && (B == C) && (C == D)) |-> (EQ === 1'b0)
    );

// Inputs outside the two GT cases keep GT low.
    check_nonqualifying_inputs_clear_gt: assert property (
        @(posedge clk) !(((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D))) |-> (GT === 1'b0)
    );

endmodule

module flag_register_sva (
    input logic IN_FLAG,
    input logic LD,
    input logic SET,
    input logic CLR,
    input logic CLK,
    input logic OUT_FLAG
);

// Load updates OUT_FLAG from IN_FLAG.
    check_load_updates_flag: assert property (
        @(posedge CLK) LD |=> (OUT_FLAG == $past(IN_FLAG))
    );

// SET drives OUT_FLAG high when load is not selected.
    check_set_updates_flag: assert property (
        @(posedge CLK) (!LD && SET) |=> (OUT_FLAG == 1'b1)
    );

// CLR drives OUT_FLAG low when neither load nor set is selected.
    check_clear_updates_flag: assert property (
        @(posedge CLK) (!LD && !SET && CLR) |=> (OUT_FLAG == 1'b0)
    );

// OUT_FLAG holds its value when no control is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LD && !SET && !CLR) |=> (OUT_FLAG == $past(OUT_FLAG))
    );

// LOAD has priority over SET and CLR.
    check_load_priority: assert property (
        @(posedge CLK) (LD && (SET || CLR)) |=> (OUT_FLAG == $past(IN_FLAG))
    );

// SET has priority over CLR when load is not asserted.
    check_set_priority_over_clear: assert property (
        @(posedge CLK) (!LD && SET && CLR) |=> (OUT_FLAG == 1'b1)
    );

endmodule

module dff_asynchronous_set_sva (
    input logic CLK,
    input logic D,
    input logic Q,
    input logic SET_B
);

// Low SET_B overrides D and forces Q high on the next cycle.
    check_set_overrides_data: assert property (
        @(posedge CLK) (SET_B == 1'b0) |=> (Q == 1'b1)
    );

// With SET_B high and D low, Q captures 0 on the next cycle.
    check_capture_zero: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b0) |=> (Q == 1'b0)
    );

// With SET_B high and D high, Q captures 1 on the next cycle.
    check_capture_one: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b1) |=> (Q == 1'b1)
    );

endmodule

