      pipeline_reg1 <= out;
      pipeline_reg2 <= pipeline_reg1;
      pipeline_reg3 <= pipeline_reg2;
      out <= pipeline_reg3 + 1;
    end
  end

endmodule

module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    input clk,  // Added clk as an input
    output EQ,
    output GT,
    output LT
);

reg [3:0] A_reg, B_reg;
reg [2:0] stage;
wire [3:0] A_next, B_next;
wire EQ_next, GT_next, LT_next;

assign EQ = (stage == 2) ? EQ_next : 1'b0;
assign GT = (stage == 2) ? GT_next : 1'b0;
assign LT = (stage == 2) ? LT_next : 1'b0;

always @(posedge clk) begin  // Corrected the always block to use clk
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            A_reg <= A_next;
            B_reg <= B_next;
            stage <= 2;
        end
        2: begin
            stage <= 0;
        end
    endcase
end

assign A_next = (A_reg > B_reg) ? A_reg : B_reg;
assign B_next = (A_reg > B_reg) ? B_reg : A_reg;
assign EQ_next = (A_next == B_next) ? 1'b1 : 1'b0;
assign GT_next = (A_next > B_next) ? 1'b1 : 1'b0;
assign LT_next = (A_next < B_next) ? 1'b1 : 1'b0;

endmodule

module calculator(a, b, op, add_out, sub_out, mul_out, div_out);

    input signed [15:0] a, b;
    input [1:0] op;
    output reg signed [15:0] add_out, sub_out, mul_out, div_out;

    always @(*) begin
        case(op)
            2'b00: begin // addition
                add_out = a + b;
                sub_out = 16'h0000;
                mul_out = 16'h0000;
                div_out = 16'h0000;
            end
            2'b01: begin // subtraction
                add_out = 16'h0000;
                sub_out = a - b;
                mul_out = 16'h0000;
                div_out = 16'h0000;
            end
            2'b10: begin // multiplication
                add_out = 16'h0000;
                sub_out = 16'h0000;
                mul_out = a * b;
                div_out = 16'h0000;
            end
            2'b11: begin // division
                add_out = 16'h0000;
                sub_out = 16'h0000;
                mul_out = 16'h0000;
                if (b != 16'h0000) begin
                    div_out = a / b;
                end else begin
                    div_out = 16'hFFFF;
                end
            end
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic signed [15:0] a,
    input logic signed [15:0] b,
    input logic [1:0] op,
    input logic signed [15:0] add_out,
    input logic signed [15:0] sub_out,
    input logic signed [15:0] mul_out,
    input logic signed [15:0] div_out
);

// Addition mode drives the sum and clears the other outputs.
    check_addition_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == calc_add(a, b)) &&
                           (sub_out == 16'sh0000) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

// Subtraction mode drives the difference and clears the other outputs.
    check_subtraction_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((add_out == 16'sh0000) &&
                           (sub_out == calc_sub(a, b)) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

// Division by zero returns 16'hFFFF and clears the other outputs.
    check_division_mode_zero_divisor: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 16'sh0000)) |-> ((add_out == 16'sh0000) &&
                                                 (sub_out == 16'sh0000) &&
                                                 (mul_out == 16'sh0000) &&
                                                 (div_out == 16'shFFFF))
    );

endmodule

