module sky130_fd_sc_ms__a221oi_sva (
    (* gclk *) input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

// Y must match the implemented A221OI boolean function.
    check_y_matches_boolean_function: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

