module BCD_to_Binary (
  input [3:0] bcd_in,
  output reg [7:0] bin_out
);

  always @* begin
    case (bcd_in)
      4'b0000: bin_out = 8'b00000000;
      4'b0001: bin_out = 8'b00000001;
      4'b0010: bin_out = 8'b00000010;
      4'b0011: bin_out = 8'b00000011;
      4'b0100: bin_out = 8'b00000100;
      4'b0101: bin_out = 8'b00000101;
      4'b0110: bin_out = 8'b00000110;
      4'b0111: bin_out = 8'b00000111;
      4'b1000: bin_out = 8'b00001000;
      4'b1001: bin_out = 8'b00001001;
      default: bin_out = 8'b00000000;
    endcase
  end

endmodule

sva:
module BCD_to_Binary_sva (
    input logic clk,
    input logic [3:0] bcd_in,
    input logic [7:0] bin_out
);

// No clock or reset exists in the RTL; sample this combinational decoder on clk.

    // BCD 0 decodes to binary 0.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd_in == 4'b0000) |-> (bin_out == 8'b00000000)
    );

// BCD 1 decodes to binary 1.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd_in == 4'b0001) |-> (bin_out == 8'b00000001)
    );

// BCD 2 decodes to binary 2.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd_in == 4'b0010) |-> (bin_out == 8'b00000010)
    );

// BCD 3 decodes to binary 3.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd_in == 4'b0011) |-> (bin_out == 8'b00000011)
    );

// BCD 4 decodes to binary 4.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd_in == 4'b0100) |-> (bin_out == 8'b00000100)
    );

// BCD 5 decodes to binary 5.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd_in == 4'b0101) |-> (bin_out == 8'b00000101)
    );

// BCD 6 decodes to binary 6.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd_in == 4'b0110) |-> (bin_out == 8'b00000110)
    );

// BCD 7 decodes to binary 7.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd_in == 4'b0111) |-> (bin_out == 8'b00000111)
    );

// BCD 8 decodes to binary 8.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd_in == 4'b1000) |-> (bin_out == 8'b00001000)
    );

// BCD 9 decodes to binary 9.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd_in == 4'b1001) |-> (bin_out == 8'b00001001)
    );

// Inputs outside valid BCD range use the default zero output.
    check_invalid_bcd_maps_to_zero: assert property (
        @(posedge clk) (bcd_in > 4'd9) |-> (bin_out == 8'b00000000)
    );

// The output never exceeds the implemented 0-to-9 range.
    check_bin_out_range: assert property (
        @(posedge clk) (bin_out <= 8'd9)
    );

endmodule

rtl:
module clk_div(
    input CLKIN,
    input RST,
    input [3:0] BAUD,
    output CLKOUT
    );

    parameter B300    = 19'b1010001011000010100;
    parameter B600    = 19'b0101000101100001010;
    parameter B1200   = 19'b0010100010110000100;
    parameter B2400   = 19'b0001010001011000010;
    parameter B4800   = 19'b0000101000101100000;
    parameter B9600   = 19'b0000010100010110000;
    parameter B19200  = 19'b0000001010001010111;
    parameter B38400  = 19'b0000000101000101011;
    parameter B57600  = 19'b0000000011011000111;
    parameter B115200 = 19'b0000000001101100011; 


    reg [19:0] clk_cntr;

    reg [19:0] baud_rate;


    reg out_clk;


    always @ (BAUD, RST) begin
      if(RST == 1'b1) begin
        baud_rate <= B9600;
      end
      else begin
        case(BAUD)
          4'h0    : baud_rate <= B300;
          4'h1    : baud_rate <= B600;
          4'h2    : baud_rate <= B1200;
          4'h3    : baud_rate <= B2400;
          4'h4    : baud_rate <= B4800;
          4'h5    : baud_rate <= B9600;
          4'h6    : baud_rate <= B19200;
          4'h7    : baud_rate <= B38400;
          4'h8    : baud_rate <= B57600;
          4'h9    : baud_rate <= B115200;
          default : baud_rate <= B9600;
        endcase   
      end
    end


    always @ (posedge CLKIN) begin
      if(RST == 1'b1) begin
        clk_cntr <= 0;
        out_clk <= 0;
      end
      else if(clk_cntr == baud_rate) begin
        clk_cntr <= 0;
        out_clk <= ~out_clk;
      end
      else begin
        clk_cntr <= clk_cntr + 1'b1;
      end
    end

   assign CLKOUT = out_clk; 



endmodule

sva:
module clk_div_sva (
    input logic        CLKIN,
    input logic        RST,
    input logic [3:0]  BAUD,
    input logic        CLKOUT,
    input logic [19:0] clk_cntr,
    input logic [19:0] baud_rate
);

// Reset forces the default baud divisor.
    check_reset_forces_default_baud: assert property (
        @(posedge CLKIN) RST |-> (baud_rate == B9600)
    );

// A reset cycle clears the counter and output by the next clock.
    check_reset_clears_counter_and_output: assert property (
        @(posedge CLKIN) RST |=> ((clk_cntr == 20'd0) && (CLKOUT == 1'b0))
    );

endmodule

module binary_counter_assertions (
    input logic clk,
    input logic rst,
    input logic up_down,
    input logic [3:0] count
);

// A sampled reset cycle leaves the counter cleared.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// In up mode below 15, the counter increments by one.
    check_up_mode_increments: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count != 4'hf)) |=> (count == ($past(count) + 4'h1))
    );

// In up mode at 15, the counter wraps to 0.
    check_up_mode_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count == 4'hf)) |=> (count == 4'h0)
    );

// In down mode above 0, the counter decrements by one.
    check_down_mode_decrements: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count != 4'h0)) |=> (count == ($past(count) - 4'h1))
    );

// In down mode at 0, the counter wraps to 15.
    check_down_mode_wraps_to_fifteen: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count == 4'h0)) |=> (count == 4'hf)
    );

endmodule

rtl:
module up_counter(
    input clk,
    input reset_n,
    output reg [2:0] count
);

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            count <= 3'b0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva(
    input logic       clk,
    input logic       reset_n,
    input logic [2:0] count
);

// Reset forces the counter to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset_n |-> (count == 3'b000)
    );

// A non-maximum count increments by one on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count != 3'b111) |=> (count == ($past(count) + 3'b001))
    );

// The maximum count wraps back to zero on the next clock.
    check_wrap_after_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count == 3'b111) |=> (count == 3'b000)
    );

endmodule

