);

// Arithmetic overflow must set Cout.
    check_overflow_sets_cout: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) > 5'd15) |-> (Cout == 1'b1)
    );

endmodule

