    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= {32'b0 | read_mux_out};
    end


  assign data_in = in_port;

endmodule

sva:
module memory_interface_sva (
    input logic [1:0]  address,
    input logic        clk,
    input logic [10:0] in_port,
    input logic        reset_n,
    input logic [31:0] readdata
);

// A clock edge with reset asserted clears readdata by the next sampled cycle.
    check_reset_clears_readdata: assert property (
        @(posedge clk)
        (!reset_n) |=> (readdata == 32'b0)
    );

// Address 0 captures in_port into readdata on the following cycle.
    check_address_zero_captures_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> (readdata == {21'b0, $past(in_port)})
    );

// Any nonzero address produces zero readdata on the following cycle.
    check_nonzero_address_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'b0)
    );

// Every non-reset update keeps the upper bits of readdata at zero.
    check_readdata_zero_extended: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:11] == 21'b0)
    );

endmodule

rtl:
module full_adder (
    COUT,
    SUM ,
    A   ,
    B   ,
    CI
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CI  ;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign {COUT, SUM} = A + B + CI;

endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

// Outputs match the 2-bit sum of the three 1-bit inputs.
    check_output_matches_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// SUM is the odd-parity function of A, B, and CI.
    check_sum_is_input_parity: assert property (
        @(posedge clk)
        SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_is_majority: assert property (
        @(posedge clk)
        COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk)
        (!A && !B && !CI) |-> ({COUT, SUM} == 2'b00)
    );

// All-one inputs produce both outputs high.
    check_all_one_inputs: assert property (
        @(posedge clk)
        (A && B && CI) |-> ({COUT, SUM} == 2'b11)
    );

// Exactly one high input produces SUM only.
    check_one_high_input: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> ({COUT, SUM} == 2'b01)
    );

// Exactly two high inputs produce COUT only.
    check_two_high_inputs: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> ({COUT, SUM} == 2'b10)
    );

endmodule

