rtl:
module decoder_3to8 (
    input A, B, C, EN, // Inputs for the decoder
    output reg [7:0] Y // 8-bit output of the decoder
);

    always @ (A, B, C, EN)
    begin
        if (EN)
        begin
            case ({A, B, C})
                3'b000: Y = 8'b00000001;
                3'b001: Y = 8'b00000010;
                3'b010: Y = 8'b00000100;
                3'b011: Y = 8'b00001000;
                3'b100: Y = 8'b00010000;
                3'b101: Y = 8'b00100000;
                3'b110: Y = 8'b01000000;
                3'b111: Y = 8'b10000000;
            endcase
        end
        else
        begin
            Y = 8'b00000000;
        end
    end
endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic EN,
    input logic [7:0] Y
);

// Disabled decoder drives all outputs low.
    check_disable_drives_zero: assert property (
        @(posedge clk) (!EN) |-> (Y == 8'b00000000)
    );

// Input 000 selects bit 0 when enabled.
    check_decode_000: assert property (
        @(posedge clk) (EN && !A && !B && !C) |-> (Y == 8'b00000001)
    );

// Input 001 selects bit 1 when enabled.
    check_decode_001: assert property (
        @(posedge clk) (EN && !A && !B && C) |-> (Y == 8'b00000010)
    );

// Input 010 selects bit 2 when enabled.
    check_decode_010: assert property (
        @(posedge clk) (EN && !A && B && !C) |-> (Y == 8'b00000100)
    );

// Input 011 selects bit 3 when enabled.
    check_decode_011: assert property (
        @(posedge clk) (EN && !A && B && C) |-> (Y == 8'b00001000)
    );

// Input 100 selects bit 4 when enabled.
    check_decode_100: assert property (
        @(posedge clk) (EN && A && !B && !C) |-> (Y == 8'b00010000)
    );

// Input 101 selects bit 5 when enabled.
    check_decode_101: assert property (
        @(posedge clk) (EN && A && !B && C) |-> (Y == 8'b00100000)
    );

// Input 110 selects bit 6 when enabled.
    check_decode_110: assert property (
        @(posedge clk) (EN && A && B && !C) |-> (Y == 8'b01000000)
    );

// Input 111 selects bit 7 when enabled.
    check_decode_111: assert property (
        @(posedge clk) (EN && A && B && C) |-> (Y == 8'b10000000)
    );

// Enabled decoder output must be one-hot encoded.
    check_enabled_output_onehot: assert property (
        @(posedge clk) EN |-> (
            (Y == 8'b00000001) ||
            (Y == 8'b00000010) ||
            (Y == 8'b00000100) ||
            (Y == 8'b00001000) ||
            (Y == 8'b00010000) ||
            (Y == 8'b00100000) ||
            (Y == 8'b01000000) ||
            (Y == 8'b10000000)
        )
    );

endmodule

module dff_reset_enable_sva (
    input logic D,
    input logic CLK,
    input logic RESET,
    input logic EN,
    input logic Q
);

// Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK)
        !RESET |-> (Q == 1'b0)
    );

// A sampled reset leaves Q low through the next clock sample.
    check_reset_value_persists_to_next_clock: assert property (
        @(posedge CLK)
        !RESET |=> (Q == 1'b0)
    );

// When enabled, Q captures D on the clock edge.
    check_load_when_enabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        EN |=> (Q == $past(D))
    );

// When disabled, Q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        !EN |=> (Q == $past(Q))
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] out
);

// A sampled reset forces the next sampled counter value to zero.
    check_reset_forces_zero_next_cycle: assert property (
        @(posedge clk)
        reset |=> (out == 4'h0)
    );

// Non-maximum values increment by one on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (out != 4'hF) |=> (out == ($past(out) + 4'h1))
    );

// The counter wraps from 15 back to zero on the next clock.
    check_wrap_after_max: assert property (
        @(posedge clk) disable iff (reset)
        (out == 4'hF) |=> (out == 4'h0)
    );

// Every active clock changes the counter value.
    check_counter_advances_each_active_cycle: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out != $past(out))
    );

endmodule

module my_module_sva (
    input logic clk,
    input logic input1,
    input logic input2,
    input logic input3,
    input logic input4,
    input logic input5,
    input logic input6,
    input logic input7,
    input logic input8,
    input logic output1
);

// First branch forces output1 high.
    check_first_branch_sets_high: assert property (
        @(posedge clk) (input1 && input2) |-> (output1 == 1'b1)
    );

// Second branch forces output1 low when the first branch is not taken.
    check_second_branch_sets_low: assert property (
        @(posedge clk) (!(input1 && input2) && !input3 && !input4) |-> (output1 == 1'b0)
    );

// Third branch forces output1 high when higher-priority branches are not taken.
    check_third_branch_sets_high: assert property (
        @(posedge clk) (!(input1 && input2) && (input3 || input4) && input5 && input6 && input7) |-> (output1 == 1'b1)
    );

// Default branch passes input8 when no earlier branch matches.
    check_default_branch_follows_input8: assert property (
        @(posedge clk) (!(input1 && input2) && (input3 || input4) && !(input5 && input6 && input7)) |-> (output1 == input8)
    );

// output1 matches the full priority-ordered combinational function.
    check_full_priority_function: assert property (
        @(posedge clk)
        output1 == ((input1 && input2) ? 1'b1 :
                    ((!input3 && !input4) ? 1'b0 :
                    ((input5 && input6 && input7) ? 1'b1 : input8)))
    );

endmodule

rtl:
module ym_sync(
  input rst,  
  input clk,
  input ym_p1,
  input ym_so,
  input ym_sh1,
  input ym_sh2,
	input ym_irq_n,
	input [7:0] ym_data,
	output reg ym_p1_sync,
	output reg ym_so_sync,
	output reg ym_sh1_sync,
	output reg ym_sh2_sync,
	output reg ym_irq_n_sync,
	output reg [7:0] ym_data_sync
);

reg p1_0, so_0, sh1_0, sh2_0, irq_0;
reg [7:0] data0;

always @(posedge ym_p1 or posedge rst ) begin : first_sync
	if( rst ) begin
		p1_0  <= 1'b0;
		so_0  <= 1'b0;
		sh1_0 <= 1'b0;
		sh2_0 <= 1'b0;
		irq_0 <= 1'b1;
		data0 <= 8'h0;
	end
	else begin
		p1_0  <= ym_p1;
		so_0  <= ym_so;
		sh1_0 <= ym_sh1;
		sh2_0 <= ym_sh2;
		irq_0 <= ym_irq_n;
		data0 <= ym_data;
	end
end

always @(posedge clk or posedge rst ) begin : second_sync
	if( rst ) begin
		ym_p1_sync    <= 1'b0;
		ym_so_sync    <= 1'b0;
		ym_sh1_sync   <= 1'b0;
		ym_sh2_sync   <= 1'b0;
		ym_irq_n_sync <= 1'b1;
		ym_data_sync  <= 8'h0;
	end
	else begin
		ym_p1_sync    <= p1_0;
		ym_so_sync    <= so_0;
		ym_sh1_sync   <= sh1_0;
		ym_sh2_sync   <= sh2_0;
		ym_irq_n_sync <= irq_0;
		ym_data_sync  <= data0;
	end
end

endmodule

module sky130_fd_sc_lp__nand3b (
    Y  ,
    A_N,
    B  ,
    C
);

    output Y  ;
    input  A_N;
    input  B  ;
    input  C  ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire not0_out   ;
    wire nand0_out_Y;

    not  not0  (not0_out   , A_N            );
    nand nand0 (nand0_out_Y, B, not0_out, C );
    buf  buf0  (Y          , nand0_out_Y    );

