module mux (
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input [1:0] sel,
    input en,
    output reg [7:0] out
);

always @(*) begin
    case(sel)
        2'b00: out = en ? in0 : 8'b0;
        2'b01: out = en ? in1 : 8'b0;
        2'b10: out = en ? in2 : 8'b0;
        2'b11: out = en ? in3 : 8'b0;
    endcase
end

endmodule

sva:
module mux_sva (
    input logic        clk,
    input logic [7:0]  in0,
    input logic [7:0]  in1,
    input logic [7:0]  in2,
    input logic [7:0]  in3,
    input logic [1:0]  sel,
    input logic        en,
    input logic [7:0]  out
);

// The output always matches the mux function.
    check_output_matches_mux_function: assert property (
        @(posedge clk)
        out == ((sel == 2'b00) ? (en ? in0 : 8'h00) :
                (sel == 2'b01) ? (en ? in1 : 8'h00) :
                (sel == 2'b10) ? (en ? in2 : 8'h00) :
                                 (en ? in3 : 8'h00))
    );

// When disabled, the output is zero.
    check_disabled_drives_zero: assert property (
        @(posedge clk) !en |-> (out == 8'h00)
