    );

// A greater than B must assert only GT.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

// A less than B must assert only LT.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

