module sky130_fd_sc_hd__or4bb (
    X  ,
    A  ,
    B  ,
    C_N,
    D_N
);

    output X  ;
    input  A  ;
    input  B  ;
    input  C_N;
    input  D_N;

    wire nand0_out;
    wire or0_out_X;

    nand nand0 (nand0_out, D_N, C_N       );
    or   or0   (or0_out_X, B, A, nand0_out);
    buf  buf0  (X        , or0_out_X      );

endmodule

sva:
module sky130_fd_sc_hd__or4bb_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C_N,
    input logic D_N
);

// No RTL clock or reset; clk is the sampling clock for this combinational cell.

    // X matches the implemented OR of A, B, and NAND(C_N, D_N).
    check_x_function: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C_N low forces X high through the NAND term.
    check_cn_low_forces_x_high: assert property (
        @(posedge clk) !C_N |-> X
    );

// D_N low forces X high through the NAND term.
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// With A and B low, X is determined only by the NAND term.
    check_nand_term_when_a_b_low: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// With C_N and D_N high, X is determined only by A or B.
    check_or_term_when_nand_inactive: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

// When all effective OR inputs are low, X is low.
    check_all_terms_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

// If X is low, all effective OR inputs must be low.
    check_x_low_requires_all_terms_low: assert property (
        @(posedge clk) !X |-> (!A && !B && C_N && D_N)
    );

endmodule

rtl:
module DFFSR (CLK, D, SET, RESET, Q, QN);
input CLK;
input D;
input SET;
input RESET;
output Q;
output QN;

reg Q;

always @(posedge CLK) begin
    if (SET) begin
        Q <= 1'b1;
    end else if (RESET) begin
        Q <= 1'b0;
    end else begin
        Q <= D;
    end
end

assign QN = ~Q;

endmodule

sva:
module DFFSR_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic RESET,
    input logic Q,
    input logic QN
);

// QN is always the inverse of Q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge CLK) disable iff (1'b0) (QN === ~Q)
    );

// SET alone drives Q high on the next cycle.
    check_set_drives_q_high: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && !RESET) |=> (Q === 1'b1)
    );

// SET has priority over RESET on the next cycle.
    check_set_overrides_reset: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && RESET) |=> (Q === 1'b1)
    );

// RESET drives Q low when SET is low.
    check_reset_drives_q_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && RESET) |=> (Q === 1'b0)
    );

// D is captured when SET and RESET are low.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && !RESET) |=> (Q === $past(D))
    );

endmodule

