module counter_module (
    input clk,
    input rst,
    output reg [31:0] count,
    output reg max_reached
);

reg [31:0] max_count = 32'hFFFFFFFF; // maximum count value

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
        max_reached <= 0;
    end
    else begin
        if (count == max_count) begin
            max_reached <= 1;
        end
        else begin
            count <= count + 1;
            max_reached <= 0;
        end
    end
end

endmodule

sva:
module counter_module_sva (
    input logic        clk,
    input logic        rst,
    input logic [31:0] count,
    input logic        max_reached
);

// Synchronous reset clears the counter and flag on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |=> (count == 32'd0) && (max_reached == 1'b0)
    );

// Below max, the counter increments by one and the flag stays low.
    check_increment_until_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != 32'hFFFFFFFF) |=> (count == ($past(count) + 32'd1)) && (max_reached == 1'b0)
    );

// At max, the counter saturates and the flag asserts.
    check_saturate_and_flag_at_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 32'hFFFFFFFF) |=> (count == $past(count)) && (max_reached == 1'b1)
    );

endmodule

rtl:
module twos_complement (
    input [3:0] in,
    output [3:0] out
);

reg [7:0] sign_extended;
reg [7:0] twos_complement;
reg [3:0] out; // Change from wire to reg

always @(*) begin
    sign_extended = { {8{in[3]}}, in };
    twos_complement = ~sign_extended + 1;
    out = twos_complement[3:0];
end

endmodule

sva:
module twos_complement_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic [3:0] out
);

// RTL is combinational; assertions sample on an external clock.

    // Output is the 4-bit two's complement of the input.
    check_exact_twos_complement: assert property (
        @(posedge clk) out == (~in + 4'b0001)
    );

// Input and output sum to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (in + out) == 4'h0
    );

// Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 4'h0)
    );

// 4'b1000 is its own two's complement.
    check_min_value_maps_to_self: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 4'h8)
    );

// Positive nonzero inputs produce a negative 4-bit result.
    check_positive_nonzero_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b0) && (in != 4'h0)) |-> (out[3] == 1'b1)
    );

// Negative inputs other than 4'b1000 produce a positive 4-bit result.
    check_negative_nonmin_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b1) && (in != 4'h8)) |-> (out[3] == 1'b0)
    );

endmodule

rtl:
module sky130_fd_sc_ls__o21ai (
    //# {{data|Data Signals}}
    input  A1  ,
    input  A2  ,
    input  B1  ,
    output Y   ,

    //# {{power|Power}}
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

    assign Y = (A1 ^ A2) ? ~B1 : (A1 & A2) ? B1 : A1 & A2;

