    check_eq_high_implies_equal: assert property (
        @(posedge clk) (EQ == 1'b1) |-> (A == B)
    );

// A low EQ must only occur for different inputs.
    check_eq_low_implies_different: assert property (
        @(posedge clk) (EQ == 1'b0) |-> (A != B)
    );

endmodule

