    check_notAM31_3_any_low_drives_high: assert property (
        @(posedge clk) (~(&AM[31:19])) |-> (notAM31_3 == 1'b1)
    );

// notAM2_0 matches the NAND of AM[2:0].
    check_notAM2_0_nand_equation: assert property (
        @(posedge clk) (notAM2_0 == ~(&AM[2:0]))
    );

// All-high AM[2:0] drives notAM2_0 low.
    check_notAM2_0_all_high_drives_low: assert property (
        @(posedge clk) (&AM[2:0]) |-> (notAM2_0 == 1'b0)
    );

// Any low bit in AM[2:0] drives notAM2_0 high.
    check_notAM2_0_any_low_drives_high: assert property (
        @(posedge clk) (~(&AM[2:0])) |-> (notAM2_0 == 1'b1)
    );

endmodule

rtl:
module bitwise_operations(
  input [7:0] a, b,
  input [2:0] op,
  output reg [7:0] result
);

  always @* begin
    case(op)
      3'b000: result = a & b;
      3'b001: result = a | b;
      3'b010: result = a ^ b;
      3'b011: result = a + b;
      3'b100: result = a - b;
      default: result = 8'b0;
    endcase
  end

endmodule

sva:
module bitwise_operations_sva(
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [2:0] op,
    input logic [7:0] result
);

// External sampling clock; the RTL is combinational and has no reset.

    // op 000 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op == 3'b000) |-> (result == (a & b))
    );

// op 001 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op == 3'b001) |-> (result == (a | b))
    );

// op 010 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op == 3'b010) |-> (result == (a ^ b))
    );

// op 011 selects addition.
    check_add_result: assert property (
        @(posedge clk) (op == 3'b011) |-> (result == (a + b))
    );

// op 100 selects subtraction.
    check_sub_result: assert property (
        @(posedge clk) (op == 3'b100) |-> (result == (a - b))
    );

// Unsupported op values drive zero.
    check_default_result: assert property (
        @(posedge clk) ((op == 3'b101) || (op == 3'b110) || (op == 3'b111)) |-> (result == 8'b0)
    );

endmodule

rtl:
module CSADD(clk, rst, x, y, ld, sum);
    input clk, rst;
    input x, y;
    input ld;
    output reg sum;

    reg sc;

    // Half Adders logic
    wire hsum1, hco1;
    assign hsum1 = y ^ sc;
    assign hco1 = y & sc;

    wire hsum2, hco2;
    assign hsum2 = x ^ hsum1;
    assign hco2 = x & hsum1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            //Reset logic goes here.
            sum <= 1'b0;
            sc <= 1'b0;
        end
        else if (ld) begin
             sum <= 1'b0;
             sc  <= 1'b0;
        end
        else begin
            //Sequential logic goes here.
            sum <= hsum2;
            sc <= hco1 ^ hco2;
        end
    end
endmodule

