rtl:
module signal_processor (
    input [15:0] input_signal,
    output reg [1:0] output_signal
);

always @(*) begin
    if (input_signal < 1000) begin
        output_signal = 2'b01;
    end else if (input_signal >= 1000 && input_signal <= 2000) begin
        output_signal = 2'b10;
    end else if (input_signal > 2000) begin
        output_signal = 2'b11;
    end
end

endmodule

sva:
module signal_processor_sva (
    input logic        clk,
    input logic [15:0] input_signal,
    input logic [1:0]  output_signal
);

// Inputs below 1000 map to 01.
    check_low_range_encoding: assert property (
        @(posedge clk) (input_signal < 16'd1000) |-> (output_signal == 2'b01)
    );

// Inputs from 1000 through 2000 map to 10.
    check_mid_range_encoding: assert property (
        @(posedge clk) ((input_signal >= 16'd1000) && (input_signal <= 16'd2000)) |-> (output_signal == 2'b10)
    );

// Inputs above 2000 map to 11.
    check_high_range_encoding: assert property (
        @(posedge clk) (input_signal > 16'd2000) |-> (output_signal == 2'b11)
    );

// Boundary value 999 stays in the low range.
    check_boundary_999: assert property (
        @(posedge clk) (input_signal == 16'd999) |-> (output_signal == 2'b01)
    );

// Boundary value 1000 enters the middle range.
    check_boundary_1000: assert property (
        @(posedge clk) (input_signal == 16'd1000) |-> (output_signal == 2'b10)
    );

// Boundary value 2000 remains in the middle range.
    check_boundary_2000: assert property (
        @(posedge clk) (input_signal == 16'd2000) |-> (output_signal == 2'b10)
    );

// Boundary value 2001 enters the high range.
    check_boundary_2001: assert property (
        @(posedge clk) (input_signal == 16'd2001) |-> (output_signal == 2'b11)
    );

endmodule

rtl:
module calculator(
    input clk,
    input rst,
    input clear,
    input [1:0] op,
    input [7:0] num1,
    input [7:0] num2,
    output [7:0] result
);

reg [7:0] temp_result;

always @ (posedge clk) begin
    if (rst) begin
        temp_result <= 0;
    end else if (clear) begin
        temp_result <= 0;
    end else begin
        case (op)
            2'b00: temp_result <= num1 + num2;
            2'b01: temp_result <= num1 - num2;
            2'b10: temp_result <= num1 * num2;
            2'b11: temp_result <= num1 / num2;
        endcase
    end
end

assign result = temp_result;

endmodule

sva:
module calculator_sva (
    input logic       clk,
    input logic       rst,
    input logic       clear,
    input logic [1:0] op,
    input logic [7:0] num1,
    input logic [7:0] num2,
    input logic [7:0] result
);

// Reset clears the registered result on the next cycle.
    check_reset_clears_result: assert property (
        @(posedge clk) rst |=> (result == 8'h00)
    );

// Clear clears the registered result on the next cycle.
    check_clear_clears_result: assert property (
        @(posedge clk) disable iff (rst)
        clear |=> (result == 8'h00)
    );

// Add operation updates result with the previous cycle sum.
    check_add_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (!clear && (op == 2'b00)) |=> (result == (($past(num1) + $past(num2)) & 8'hFF))
    );

// Subtract operation updates result with the previous cycle difference.
    check_sub_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (!clear && (op == 2'b01)) |=> (result == (($past(num1) - $past(num2)) & 8'hFF))
    );

endmodule

rtl:
module d_latch (
    input D,
    input S,
    input R,
    input CLK,
    output Q
);

reg Q;

always @(posedge CLK) begin
    if (R) begin
        Q <= 0;
    end else if (S) begin
        Q <= 1;
    end else begin
        Q <= D;
    end
end

endmodule

sva:
module d_latch_sva (
    input logic D,
    input logic S,
    input logic R,
    input logic CLK,
    input logic Q
);

// If R is high at a clock edge, Q is cleared on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge CLK) disable iff (1'b0)
        R |=> (Q == 1'b0)
    );

// If S is high while R is low, Q is set on the next sampled cycle.
    check_set_sets_q: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && S) |=> (Q == 1'b1)
    );

// If neither R nor S is high, Q captures D on the next sampled cycle.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && !S) |=> (Q == $past(D))
    );

// If both R and S are high, R has priority and Q is cleared.
    check_reset_priority_over_set: assert property (
        @(posedge CLK) disable iff (1'b0)
        (R && S) |=> (Q == 1'b0)
    );

// On every cycle, Q matches the previous cycle's selected input.
    check_full_next_state_function: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q == ($past(R) ? 1'b0 : ($past(S) ? 1'b1 : $past(D))))
    );

endmodule

