module check_tuple(
  input [2:0] tuple,
  output valid
);

  wire a = tuple[0] ^ tuple[1];
  wire b = tuple[1] ^ tuple[2];
  wire c = tuple[0] ^ tuple[2];

  assign valid = (a == tuple[2]) && (b == tuple[0]) && (c == tuple[1]);

endmodule

sva:
module check_tuple_sva(
    input logic clk,
    input logic [2:0] tuple,
    input logic valid
);

// Combinational DUT sampled on clk; the RTL has no reset.

    // valid must match the RTL expression exactly.
    check_valid_definition: assert property (
        @(posedge clk) disable iff (1'b0)
            valid == (((tuple[0] ^ tuple[1]) == tuple[2]) &&
                      ((tuple[1] ^ tuple[2]) == tuple[0]) &&
                      ((tuple[0] ^ tuple[2]) == tuple[1]))
    );

// valid is high exactly for even-parity tuples.
    check_valid_even_parity: assert property (
        @(posedge clk) disable iff (1'b0)
            valid == (~^tuple)
    );

// A high valid requires tuple[0] ^ tuple[1] to equal tuple[2].
    check_valid_implies_xor01_eq_2: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[0] ^ tuple[1]) == tuple[2])
    );

// A high valid requires tuple[1] ^ tuple[2] to equal tuple[0].
    check_valid_implies_xor12_eq_0: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[1] ^ tuple[2]) == tuple[0])
    );

// A high valid requires tuple[0] ^ tuple[2] to equal tuple[1].
    check_valid_implies_xor02_eq_1: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[0] ^ tuple[2]) == tuple[1])
    );

// tuple[0] ^ tuple[1] matching tuple[2] is sufficient for valid.
    check_xor01_eq_2_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[0] ^ tuple[1]) == tuple[2]) |-> valid
    );

// tuple[1] ^ tuple[2] matching tuple[0] is sufficient for valid.
    check_xor12_eq_0_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[1] ^ tuple[2]) == tuple[0]) |-> valid
    );

// tuple[0] ^ tuple[2] matching tuple[1] is sufficient for valid.
    check_xor02_eq_1_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[0] ^ tuple[2]) == tuple[1]) |-> valid
    );

endmodule

rtl:
module delay_gate (
    input in,
    input rst,
    input en,
    input clk,
    output reg out
);

    reg [3:0] delay_reg;
    wire [3:0] next_delay_reg;

    always @(posedge clk) begin
        if (rst) begin
            delay_reg <= 4'b0000;
        end else if (en) begin
            delay_reg <= next_delay_reg;
        end
    end

    assign next_delay_reg[0] = in;
    assign next_delay_reg[1] = delay_reg[0];
    assign next_delay_reg[2] = delay_reg[1];
    assign next_delay_reg[3] = delay_reg[2];

    always @(*) begin
        out = delay_reg[3];
    end

endmodule

sva:
module delay_gate_sva (
    input logic       in,
    input logic       rst,
    input logic       en,
    input logic       clk,
    input logic       out,
    input logic [3:0] delay_reg,
    input logic [3:0] next_delay_reg
);

// Clock: clk
    // Reset: rst, active-high synchronous
    // Logic: sequential delay_reg with combinational next_delay_reg and out

    // next_delay_reg is the shifted version of delay_reg with in loaded into bit 0.
    check_next_delay_reg_wiring: assert property (
        @(posedge clk) disable iff (rst)
        next_delay_reg == {delay_reg[2], delay_reg[1], delay_reg[0], in}
    );

// out always reflects the most significant bit of delay_reg.
    check_out_matches_delay_reg_msb: assert property (
        @(posedge clk) disable iff (rst)
        out == delay_reg[3]
    );

endmodule

rtl:
module fifo_read_counter(
    out,
    O1,
    sel,
    rd_clk,
    Q
);

    output [11:0] out;
    output [11:0] O1;
    input sel;
    input rd_clk;
    input Q;

    reg [11:0] out;
    reg [11:0] O1;

    always @(posedge rd_clk) begin
        if(Q) begin
            out <= 12'h0;
            O1 <= 12'h0;
        end else if(sel) begin
            out <= out + 1;
            O1 <= out;
        end
    end

endmodule

sva:
module fifo_read_counter_sva (
    input logic [11:0] out,
    input logic [11:0] O1,
    input logic sel,
    input logic rd_clk,
    input logic Q
);

// Q clears both registers on the next sampled cycle.
    check_sync_clear: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        Q |=> (out == 12'h000 && O1 == 12'h000)
    );

// Q has priority over sel when both are high.
    check_clear_priority_over_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (Q && sel) |=> (out == 12'h000 && O1 == 12'h000)
    );

// sel increments out when Q is low.
    check_out_increments_on_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == ($past(out) + 12'd1))
    );

// sel loads O1 with the previous out value when Q is low.
    check_o1_captures_previous_out: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (O1 == $past(out))
    );

// With Q low and sel low, both registers hold their values.
    check_hold_when_idle: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && !sel) |=> (out == $past(out) && O1 == $past(O1))
    );

// After a sel update, out is exactly one count ahead of O1.
    check_sel_creates_expected_offset: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == (O1 + 12'd1))
    );

endmodule

rtl:
module adder_subtractor (
    input [7:0] A,
    input [7:0] B,
    input CIN,
    input SUB,
    output reg [7:0] SUM,
    output reg OVF
);

    reg [8:0] temp_sum;
    reg [7:0] temp_a;
    reg [7:0] temp_b;

    always @(*) begin
        if (SUB == 1'b1) begin
            temp_a = A;
            temp_b = ~B + 1;
        end
        else begin
            temp_a = A;
            temp_b = B;
        end

        if (CIN == 1'b1) begin
            temp_sum = {1'b1, temp_a} + {1'b1, temp_b};
        end
        else begin
            temp_sum = temp_a + temp_b;
        end

        if (temp_sum[8] == 1'b1) begin
            OVF = 1'b1;
        end
        else begin
            OVF = 1'b0;
        end

        SUM = temp_sum[7:0];
    end

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic CIN,
    input logic SUB,
    input logic [7:0] SUM,
    input logic OVF
);

// In add mode, SUM is the low 8 bits of A plus B.
    check_add_mode_sum: assert property (
        @(posedge clk)
        (!SUB) |-> (SUM == (A + B))
    );

// In subtract mode, SUM is the low 8 bits of A plus two's-complement B.
    check_sub_mode_sum: assert property (
        @(posedge clk)
        (SUB) |-> (SUM == (A + (~B + 8'h01)))
    );

// With CIN high in add mode, outputs match the 9-bit sum of A and B.
    check_add_with_cin: assert property (
        @(posedge clk)
        (!SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, B}))
    );

// With CIN high in subtract mode, outputs match the 9-bit sum of A and two's-complement B.
    check_sub_with_cin: assert property (
        @(posedge clk)
        (SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, (~B + 8'h01)}))
    );

endmodule

rtl:
module bitwise_xor(busA, busB, busXOR);

input [7:0] busA;
input [7:0] busB;
output [7:0] busXOR;

wire [7:0] temp1, temp2, temp3, temp4;

// XOR operation
assign temp1 = busA ^ busB;

// Invert the inputs
assign temp2 = ~busA;
assign temp3 = ~busB;

// AND operation
assign temp4 = temp2 & temp3;

// Final XOR operation
assign busXOR = temp1 ^ temp4;

endmodule

sva:
module bitwise_xor_sva (
    input logic        clk,
    input logic [7:0]  busA,
    input logic [7:0]  busB,
    input logic [7:0]  busXOR,
    input logic [7:0]  temp1,
    input logic [7:0]  temp2,
    input logic [7:0]  temp3,
    input logic [7:0]  temp4
);

// busXOR simplifies to the bitwise NAND of the inputs.
    check_output_nand_function: assert property (
        @(posedge clk) busXOR == (~(busA & busB))
    );

endmodule

