module counter (
  input clk,
  input rst,
  output reg [3:0] count
);

  always @(posedge clk) begin
    if (rst) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

// clk is the only clock; rst is an active-high synchronous reset.

    // A reset cycle clears count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// On each non-reset cycle, count increments by one on the next cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'h1))
    );

// A maximum count value rolls over to zero on the next non-reset cycle.
    check_count_rollover: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module top_module ( 
    input [3:0] in, // 4-to-2 encoder inputs 
    input clk, // clock input for shift register 
    input d, // data input for shift register 
    output [2:0] q, // 3-bit output from shift register 
    output [1:0] pos, // 2-bit output from 4-to-2 encoder 
    output [0:0] out // 1-bit output from functional module 
);

    // 4-to-2 encoder
    wire [1:0] enc_out;
    assign pos = enc_out;
    assign enc_out[0] = (in[3] | in[2] | in[1] | in[0]) ? 0 : 1;
    assign enc_out[1] = (in[3] & ~in[2] & ~in[1] & ~in[0]) ? 1 :
                       (in[3] & in[2] & ~in[1] & ~in[0]) ? 2 :
                       (in[3] & in[2] & in[1] & ~in[0]) ? 3 :
                       (in[3] & in[2] & in[1] & in[0]) ? 3 :
                       (in[3] & in[2] & ~in[1] & in[0]) ? 2 :
                       (in[3] & ~in[2] & ~in[1] & in[0]) ? 1 : 0;

    // 3-bit shift register
    reg [2:0] shift_reg;
    always @(posedge clk) begin
        shift_reg <= {shift_reg[1:0], d};
    end
    assign q = shift_reg;

    // Functional module
    wire [1:0] xor_in;
    assign xor_in = {enc_out[1], shift_reg[2]};
    assign out = xor_in[0] ^ xor_in[1];

endmodule

sva:
module top_module_sva (
    input logic [3:0] in,
    input logic clk,
    input logic d,
    input logic [2:0] q,
    input logic [1:0] pos,
    input logic [0:0] out
);

// pos[0] is high only when all encoder inputs are low.
    check_encoder_pos_lsb: assert property (
        @(posedge clk) pos[0] == ~(|in)
    );

// pos[1] matches the implemented enc_out[1] truth table.
    check_encoder_pos_msb: assert property (
        @(posedge clk) pos[1] == (in[3] & ~(in[2] ^ in[1]))
    );

// q[0] captures d from the previous clock edge.
    check_shift_reg_q0_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[0] == $past(d))
    );

// q[1] captures the previous value of q[0].
    check_shift_reg_q1_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[1] == $past(q[0]))
    );

// q[2] captures the previous value of q[1].
    check_shift_reg_q2_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[2] == $past(q[1]))
    );

// out is the XOR of q[2] and the encoder MSB.
    check_out_xor_function: assert property (
        @(posedge clk) out[0] == (q[2] ^ pos[1])
    );

endmodule

rtl:
module my_module (i_0r0, i_0r1, i_0a, o_0r0, o_0r1, o_0a, reset);
  input i_0r0;
  input i_0r1;
  output i_0a;
  output o_0r0;
  output o_0r1;
  input o_0a;
  input reset;

  wire bna_0;
  wire tech1_oint;
  wire tech2_oint;
  wire bcomp_0;

  and (o_0r0, i_0r0, bna_0);
  nand (tech1_oint, o_0r0, reset);
  and (o_0r1, i_0r1, bna_0);
  nand (tech2_oint, o_0r1, reset);

  not (bna_0, o_0a);

  or (bcomp_0, o_0r0, o_0r1);
  buf (i_0a, bcomp_0);
endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic i_0r0,
    input logic i_0r1,
    input logic i_0a,
    input logic o_0r0,
    input logic o_0r1,
    input logic o_0a,
    input logic reset
);

// o_0r0 is i_0r0 gated by the inverse of o_0a.
    check_o0r0_gate: assert property (
        @(posedge clk) disable iff (reset)
        o_0r0 == (i_0r0 & ~o_0a)
    );

// o_0r1 is i_0r1 gated by the inverse of o_0a.
    check_o0r1_gate: assert property (
        @(posedge clk) disable iff (reset)
        o_0r1 == (i_0r1 & ~o_0a)
    );

// i_0a is the OR of the two output request signals.
    check_i0a_from_outputs: assert property (
        @(posedge clk) disable iff (reset)
        i_0a == (o_0r0 | o_0r1)
    );

// i_0a equals the gated OR of the two input request signals.
    check_i0a_from_inputs: assert property (
        @(posedge clk) disable iff (reset)
        i_0a == ((i_0r0 | i_0r1) & ~o_0a)
    );

// o_0a high blocks o_0r0.
    check_o0a_blocks_o0r0: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !o_0r0
    );

// o_0a high blocks o_0r1.
    check_o0a_blocks_o0r1: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !o_0r1
    );

// o_0a high blocks i_0a.
    check_o0a_blocks_i0a: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !i_0a
    );

// o_0r0 can only be high when i_0r0 is high and o_0a is low.
    check_o0r0_source_conditions: assert property (
        @(posedge clk) disable iff (reset)
        o_0r0 |-> (i_0r0 && !o_0a)
    );

// o_0r1 can only be high when i_0r1 is high and o_0a is low.
    check_o0r1_source_conditions: assert property (
        @(posedge clk) disable iff (reset)
        o_0r1 |-> (i_0r1 && !o_0a)
    );

// Any asserted output request drives i_0a high.
    check_output_request_sets_i0a: assert property (
        @(posedge clk) disable iff (reset)
        (o_0r0 || o_0r1) |-> i_0a
    );

endmodule

