module DFlipFlop_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic q
);

// clk is the clock; reset is an active-low asynchronous reset; q captures d on rising clk.

    // q is held low whenever reset is asserted.
    check_q_low_during_reset: assert property (
        @(posedge clk)
        !reset |-> (q == 1'b0)
