module boolean_ops (
   // Outputs
   logic_out, 
   // Inputs
   rs1_data, rs2_data, isand, isor, isxor, pass_rs2_data, inv_logic, 
   ifu_exu_sethi_inst_e
   );

   input [63:0] rs1_data;             // 1st input operand
   input [63:0] rs2_data;             // 2nd input operand
   input isand;
   input isor;
   input isxor;
   input pass_rs2_data;
   input inv_logic;
   input ifu_exu_sethi_inst_e;       // zero out top half of rs2 on mov

   output [63:0] logic_out;      // output of logic block

   wire [63:0] rs1_data_bf1;                 // buffered rs1_data
   wire [63:0] rs2_data_bf1;                 // buffered rs2_data
   wire [63:0] mov_data;
   wire [63:0] result_and;              // rs1_data & rs2_data
   wire [63:0] result_or;               // rs1_data | rs2_data
   wire [63:0] result_xor;              // rs1_data ^ rs2_data
   wire [63:0] rs2_xor_invert;           // output of mux between various results

   // buffer inputs
   assign rs1_data_bf1 = rs1_data;
   assign rs2_data_bf1 = rs2_data;

   // zero out top of rs2 for sethi_inst
   assign mov_data[63:32] = rs2_data_bf1[63:32] & {32{~ifu_exu_sethi_inst_e}};
   assign mov_data[31:0] = rs2_data_bf1[31:0];

   // invert input2 for andn, orn, xnor
   assign rs2_xor_invert = rs2_data_bf1 ^ {64{inv_logic}};

   // do boolean ops
   assign result_and = rs1_data_bf1 & rs2_xor_invert;
   assign result_or = rs1_data_bf1 | rs2_xor_invert;
   assign result_xor = rs1_data_bf1 ^ rs2_xor_invert;

   // mux between various results
   assign logic_out = (isand) ? result_and: 
                        (isor) ? result_or:
                        (isxor) ? result_xor:
                        mov_data;

endmodule

sva:
module boolean_ops_sva (
    input logic        clk,
    input logic [63:0] rs1_data,
    input logic [63:0] rs2_data,
    input logic        isand,
    input logic        isor,
    input logic        isxor,
    input logic        pass_rs2_data,
    input logic        inv_logic,
    input logic        ifu_exu_sethi_inst_e,
    input logic [63:0] logic_out
);

// logic_out must match the implemented priority mux and datapath.
    check_logic_out_mux_function: assert property (
        @(posedge clk)
        logic_out == (
            isand ? (rs1_data & (rs2_data ^ {64{inv_logic}})) :
            isor  ? (rs1_data | (rs2_data ^ {64{inv_logic}})) :
            isxor ? (rs1_data ^ (rs2_data ^ {64{inv_logic}})) :
                    {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

// isand selects the AND path regardless of other select inputs.
    check_and_selected: assert property (
        @(posedge clk)
        isand |-> (logic_out == (rs1_data & (rs2_data ^ {64{inv_logic}})))
    );

// isor selects the OR path when isand is not asserted.
    check_or_selected: assert property (
        @(posedge clk)
        (!isand && isor) |-> (logic_out == (rs1_data | (rs2_data ^ {64{inv_logic}})))
    );

// isxor selects the XOR path when higher-priority selects are not asserted.
    check_xor_selected: assert property (
        @(posedge clk)
        (!isand && !isor && isxor) |-> (logic_out == (rs1_data ^ (rs2_data ^ {64{inv_logic}})))
    );

// With no boolean select asserted, logic_out must follow mov_data.
    check_mov_selected: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out == {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

// In mov mode, the upper half is masked off only by ifu_exu_sethi_inst_e.
    check_mov_upper_half_masked: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out[63:32] == (rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}})
        )
    );

// In mov mode, the lower half always passes rs2_data unchanged.
    check_mov_lower_half_passes_rs2: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (logic_out[31:0] == rs2_data[31:0])
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,
    input [31:0] in,
    input select,
    output q
);

    wire [31:0] out_module1;
    wire q_module2;
    wire [31:0] out_functional;

    module1 module1_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out_module1)
    );

    module2 module2_inst (
        .clk(clk),
        .d(out_module1[0]),
        .q(q_module2)
    );

    functional_module functional_module_inst (
        .out_module1(out_module1),
        .q_module2(q_module2),
        .select(select),
        .out(out_functional)
    );

    assign q = out_functional[0];

endmodule
module module1 (
    input clk,
    input reset,
    input [31:0] in,
    output [31:0] out
);

    reg [31:0] out_reg;

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 0;
        end else begin
            out_reg <= {out_reg[30:0], in[31]};
        end
    end

    assign out = out_reg;

endmodule
module module2 (
    input clk,
    input d,
    output q
);

    reg q_reg;

    always @(posedge clk) begin
        q_reg <= d;
    end

    assign q = q_reg;

endmodule
module functional_module (
    input [31:0] out_module1,
    input q_module2,
    input select,
    output [31:0] out
);

    assign out = select ? out_module1 : {31'b0, q_module2};

endmodule

