module adder4bit(
  input [3:0] A, B,
  input Cin,
  output [3:0] S,
  output Cout
  );

  wire [3:0] sum;
  wire C1, C2, C3;

  // Full adder for bit 0
  full_adder fa0(A[0], B[0], Cin, sum[0], C1);

  // Full adder for bit 1
  full_adder fa1(A[1], B[1], C1, sum[1], C2);

  // Full adder for bit 2
  full_adder fa2(A[2], B[2], C2, sum[2], C3);

  // Full adder for bit 3
  full_adder fa3(A[3], B[3], C3, sum[3], Cout);

  assign S = sum;

endmodule

module full_adder(
  input A, B, Cin,
  output S, Cout
  );

  assign S = A ^ B ^ Cin;
  assign Cout = (A & B) | (Cin & (A ^ B));

endmodule

sva:
module adder4bit_sva(
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

// Combined carry and sum must match 4-bit addition with carry-in.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

// Bit 0 sum must implement the full-adder XOR equation.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Lower two sum bits must match the 2-bit addition result.
    check_low2_sum: assert property (
        @(posedge clk) S[1:0] == (A[1:0] + B[1:0] + Cin)
    );

// Lower three sum bits must match the 3-bit addition result.
    check_low3_sum: assert property (
        @(posedge clk) S[2:0] == (A[2:0] + B[2:0] + Cin)
    );

// Zero B and zero carry-in must pass A through with no carry-out.
    check_b_zero_passthrough: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

// Zero A and zero carry-in must pass B through with no carry-out.
    check_a_zero_passthrough: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

// Zero A and zero B must pass Cin into the least-significant sum bit only.
    check_cin_only_behavior: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == {3'b000, Cin}) && (Cout == 1'b0))
    );

// Carry-out must be asserted exactly when the 5-bit sum exceeds 15.
    check_cout_threshold: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin}) > 5'd15)
    );

endmodule

rtl:
module sel_logic (
    input [1:0] sel,
    input A,
    input B,
    output Y
);

    wire xor_out;
    wire and_out;
    wire or_out;
    wire nand_out;

    assign xor_out = A ^ B;
    assign and_out = A & B;
    assign or_out = A | B;
    assign nand_out = ~(A & B);

    assign Y = (sel == 0) ? xor_out :
               (sel == 1) ? and_out :
               (sel == 2) ? or_out :
                            nand_out;

endmodule

sva:
module sel_logic_sva (
    input logic clk,
    input logic [1:0] sel,
    input logic A,
    input logic B,
    input logic Y
);

// RTL is combinational with no reset; clk is the SVA sampling clock.

    // Y must match the selected boolean function.
    check_y_functional_equivalence: assert property (
        @(posedge clk)
        Y == ((sel == 2'b00) ? (A ^ B) :
              (sel == 2'b01) ? (A & B) :
              (sel == 2'b10) ? (A | B) :
                               ~(A & B))
    );

// sel=00 selects XOR of A and B.
    check_sel_xor: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (Y == (A ^ B))
    );

// sel=01 selects AND of A and B.
    check_sel_and: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (Y == (A & B))
    );

// sel=10 selects OR of A and B.
    check_sel_or: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (Y == (A | B))
    );

// sel=11 selects NAND of A and B.
    check_sel_nand: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (Y == ~(A & B))
    );

endmodule

module binary_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

// Reset clears count on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Count wraps from 9 back to 0 when not in reset.
    check_wrap_at_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'b1001) |=> (count == 4'b0000)
    );

// Count increments by one on all other non-reset cycles.
    check_increment_otherwise: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'b1001) |=> (count == ($past(count) + 4'b0001))
    );

endmodule
